/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,o,k,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:o,answer:o[k],explain:x});
const C=(w,s,d,en,zh,st,g,r)=>({senseId:`${w}.s${s}`,domain:d,en,zh,structure:st,grammar:g,rationale:r,sourceType:'authored'});
const M=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[C(w,...c)],mistakes:[M(...m)],quiz:qs.map((q,i)=>Q(w,i+1,q[0],q[1],q[2],q[3],q[4]))});
P('flippancy','由形容词 flippant 加名词后缀 -cy 构成，表示对严肃事情缺乏尊重地开玩笑或轻率对待。',[1,'公共讨论','The minister’s flippancy about the flood victims angered residents, who expected a serious account of the delayed rescue response.','部长拿洪灾受害者开玩笑，引起居民愤怒；他们希望听到对救援延误的严肃说明。','The minister’s flippancy about the flood victims / angered residents, / who expected a serious account of the delayed rescue response.','不可数名词；常与 about 连用，指不合时宜的轻佻，而非一般幽默感。','部长对受灾者开玩笑，显示缺少应有的严肃和尊重。'],['The reporter’s flippancy showed respect when she solemnly listened to the families and made no jokes about their loss.','The reporter’s seriousness showed respect when she solemnly listened to the families and made no jokes about their loss.','认真倾听且不拿损失开玩笑体现严肃，不是 flippancy。'],[[1,'Flippancy about a tragedy is?',['an inappropriate lack of seriousness','a carefully researched explanation','a quiet refusal to speak'],0,'flippancy 指对严肃事项轻率、缺乏尊重。'],[1,'Which response shows flippancy?',['joking about a family’s recent loss during a formal condolence visit','offering sincere sympathy','asking how practical help can be provided'],0,'在吊唁时拿丧亲开玩笑是不合时宜的。'],[1,'Flippancy differs from harmless humour because it can suggest?',['disrespect toward a serious matter','careful attention to evidence','a lack of any spoken words'],0,'该词带有对严肃事情不够尊重的意味。'],[1,'Choose the natural phrase.',['his flippancy about the emergency','his flippancy under a bridge yesterday','flippancy to arrive early'],0,'flippancy about + 主题是自然搭配。']]);
P('flipper','由 flip 与施事后缀 -er 构成；可指海豹、企鹅等动物宽而扁的肢体，也指游泳者穿戴的橡胶脚蹼。',[1,'海洋生物','The seal propelled itself through the water with each front flipper, steering toward the rocky ledge where its pup waited.','海豹用两只前鳍推动身体在水中前行，并转向幼崽等候的岩礁。','The seal propelled itself through the water with each front flipper, / steering toward the rocky ledge / where its pup waited.','s1 指动物肢体，s2 指游泳者穿戴的脚蹼；依据是动物身体部位还是橡胶装备。','海豹用自身的前肢游泳，体现动物的 flipper。'],['The diver’s flipper was a natural limb growing from the seal’s body, not a piece of swimming equipment.','The diver’s flipper was a rubber blade worn on the foot, not a natural animal limb.','潜水者穿戴的是橡胶脚蹼，属于 flipper 的 s2。'],[[1,'A penguin’s flipper is?',['a broad limb used to move through water','a rubber shoe worn by a diver','a feather on its head'],0,'flipper s1 指企鹅等动物的鳍状肢。'],[2,'A swimmer puts on flippers to?',['gain propulsion in the water','protect the hands from cold air','measure the depth of a pool'],0,'flipper s2 是穿在脚上的游泳脚蹼。'],[1,'Which use refers to an animal’s own body?',['the seal turned with its left flipper','the diver packed a pair of rubber flippers','the swimmer rented fins at the pool'],0,'海豹身体上的肢体对应 s1。'],[2,'Choose the natural phrase for equipment.',['a pair of diving flippers','a penguin wore rubber feet naturally','a flipper of water'],0,'diving flippers 指潜水用脚蹼。']]);
P('floodplain','由 flood 与 plain 组合而成，指河流旁低平、由沉积物形成且可能被洪水淹没的地带。',[1,'地理','The town restricted new housing on the floodplain because seasonal river floods regularly spread silt across the low fields.','由于季节性河洪常把淤泥铺到低洼田地上，镇里限制在洪泛平原新建住宅。','The town restricted new housing on the floodplain / because seasonal river floods regularly spread silt / across the low fields.','可数名词；通常靠近河道，土壤由沉积形成，洪水风险较高。','低洼临河地带会被洪水覆盖并积淤泥，符合 floodplain。'],['The map labelled the steep mountain summit a floodplain because it stood high above the river and could never be inundated.','The map labelled the low ground beside the river a floodplain because it could be inundated.','远离河流且高耸的山顶不是可能受淹的洪泛平原。'],[[1,'A floodplain is generally?',['low land beside a river that may be covered by floods','a steep ridge far from any water','a wall built to stop all rainfall'],0,'洪泛平原是临河低地，可能遭洪水淹没。'],[1,'Why can floodplain soil be fertile?',['floodwater deposits sediment there','the ground is made only of bare rock','it receives no water at any time'],0,'洪水携带并沉积的泥沙可增加土壤养分。'],[1,'Which place is most likely a floodplain?',['a flat field along a river bend','a high dry plateau','a deep ocean trench'],0,'河流旁平坦低地符合定义。'],[1,'Building restrictions on a floodplain often address?',['the risk of inundation','the risk of volcanic ash only','the lack of any nearby river'],0,'洪泛平原有周期性淹水风险。']]);
P('flor','源自西班牙语 flor“花”，在雪利酒酿造中指漂浮于酒液表面的酵母层，会影响酒的风味。',[1,'葡萄酒酿造','The winemaker protected the sherry beneath a layer of flor, whose surface yeast altered the wine’s aroma while limiting contact with air.','酿酒师让雪利酒表面保持一层 flor；这层酵母改变酒香，同时减少酒液与空气接触。','The winemaker protected the sherry beneath a layer of flor, / whose surface yeast altered the wine’s aroma / while limiting contact with air.','专业名词，常见于雪利酒传统；这里指酒面浮生的酵母膜，不是一般花朵或葡萄品种。','雪利酒表面的漂浮酵母膜正是 flor。'],['The cellar worker called the wooden barrel’s metal hoop flor because it was a flower-shaped decoration around the cask.','The cellar worker called the floating yeast film on the sherry flor.','酿酒术语 flor 指酒面酵母层，不是桶箍或花形装饰。'],[[1,'In sherry production, flor is?',['a surface layer of yeast that affects the wine','a type of wooden barrel','a flower added as a garnish'],0,'flor 是漂浮在某些雪利酒表面的酵母层。'],[1,'What can flor influence?',['the flavour and aroma of sherry','the shape of the vineyard hills','the colour of the wine label only'],0,'酒面酵母层会影响酒的风味。'],[1,'A winemaker preserving flor would protect?',['the yeast film floating on the wine','the cork after the bottle is empty','the flower beds outside the cellar'],0,'此处的 flor 是漂浮酵母膜。'],[1,'Choose the correct domain for flor in this sense.',['sherry-making','ship navigation','computer graphics'],0,'该词的专门义属于雪利酒酿造。']]);
P('floral','源自拉丁语 floralis“花的”，由 flos“花”派生；可表示与花有关，也可指装饰有花卉图案。',[1,'纺织设计','The designer chose a floral print with small blue blossoms for the curtains, while keeping the cushions plain so the room would not feel crowded.','设计师为窗帘选了蓝色小花的花卉图案，同时让靠垫保持素色，以免房间显得拥挤。','The designer chose a floral print / with small blue blossoms for the curtains, / while keeping the cushions plain so the room would not feel crowded.','s1 泛指花的、由花构成；s2 指印花或装饰图案带花卉设计。','布面装饰蓝色花朵图样，对应 floral 的花卉图案义。'],['The curtain’s floral pattern consisted only of plain grey squares and contained no flower shapes or botanical designs.','The curtain’s geometric pattern consisted only of plain grey squares.','没有花朵或植物图案时，不能称 floral pattern。'],[[1,'Floral fragrance is?',['a scent associated with flowers','a smell produced by metal tools','a sound made by a bird'],0,'floral s1 表示与花有关。'],[2,'A floral wallpaper pattern is decorated with?',['flower designs','plain numbers only','photographs of machinery'],0,'floral s2 指带花卉图案的装饰。'],[1,'Which phrase uses floral in its broader “of flowers” sense?',['floral scent from fresh roses','a floral print on a dress','a floral design painted on a box'],0,'玫瑰散发的香气属于花相关的气味。'],[2,'Choose the natural phrase for a fabric design.',['a floral skirt','floral to walk','a floral of the room'],0,'floral 可作形容词修饰 skirt。']]);
P('florid','源自拉丁语 floridus“开花的、红润的”，经法语进入英语；可指辞藻过度华丽，也可指脸色红润。',[1,'文学评论','The critic called the speech florid because its long metaphors and ornate phrases obscured the speaker’s simple argument.','评论家认为这篇演讲辞藻浮华，因为冗长的隐喻和华丽措辞遮蔽了简单论点。','The critic called the speech florid / because its long metaphors and ornate phrases / obscured the speaker’s simple argument.','s1 指语言或装饰过分华丽；s2 指面色红润。褒贬依语境，但写作义常带批评。','华丽措辞盖过论点，体现 florid 的辞藻义。'],['The patient’s florid complexion was pale and grey after the long illness, with no trace of redness.','The patient’s pallid complexion was pale and grey after the long illness.','苍白灰暗不是红润的 florid complexion，应改为 pallid。'],[[1,'A florid style of writing is often?',['ornate and excessively elaborate','plain and spare','composed only of numbers'],0,'florid s1 描写辞藻繁复、华丽。'],[2,'A florid face appears?',['red or flushed','blue with ink','completely colourless'],0,'florid s2 指面色红润。'],[1,'Which sentence might a critic call florid?',['The prose piles up showy descriptions until the point is lost.','The report states the result in one clear sentence.','The chart contains no decorative language.'],0,'华丽堆砌遮蔽主旨是 florid 的写作义。'],[2,'After running up the hill, his florid cheeks were?',['reddened and flushed','pale from lack of colour','covered with flower petals'],0,'运动后脸颊发红符合 florid s2。']]);
P('florist','由法语 fleuriste“花商”进入英语，词源与拉丁语 flos“花”同源，指卖花的人或花店。',[1,'日常购物','The florist wrapped the lilies in damp paper and placed them in a cool box so they would stay fresh for the wedding ceremony.','花商把百合花用湿纸包好，放入凉爽的盒子，以便它们在婚礼仪式前保持新鲜。','The florist wrapped the lilies in damp paper / and placed them in a cool box / so they would stay fresh for the wedding ceremony.','可数名词；依语境可指从业者或经营鲜花的店铺。','包装鲜花并保鲜的人是 florist。'],['The florist repaired the customer’s car engine in the garage, although the shop sold only flowers and floral supplies.','The mechanic repaired the customer’s car engine in the garage.','修车是 mechanic 的工作，不是花商 florist 的工作。'],[[1,'A florist mainly?',['sells and arranges flowers','repairs household wiring','writes weather forecasts'],0,'florist 指卖花或制作花艺的人。'],[1,'“I bought the bouquet at the florist’s” most likely means?',['I bought it at a flower shop.','I bought it at a car repair shop.','I bought it from a river ferry.'],0,'florist’s 可指花店。'],[1,'Which task belongs to a florist?',['arranging roses for a customer','diagnosing a broken transmission','mapping a floodplain'],0,'花艺师会为顾客整理花束。'],[1,'Choose the natural phrase.',['ask the florist to prepare a bouquet','ask the florist to forecast rainfall','ask the florist for a passport renewal'],0,'顾客可请花商准备花束。']]);
P('flotation','由 float 加 -ation 构成；指物体漂浮或利用浮力分离矿物，也可指公司首次向公众发行股票。',[2,'金融市场','The company’s flotation on the stock exchange raised capital from public investors, although its founders retained a controlling share.','公司通过在证券交易所首次发行股票从公众投资者处筹集资金，同时创始人保留了控股股份。','The company’s flotation on the stock exchange raised capital / from public investors, / although its founders retained a controlling share.','s1 指漂浮或浮选；s2 为英式金融用语，指公司首次公开发行股票。','公司首次向公众发行股份筹资，对应金融义 s2。'],['The company cancelled its flotation because no shares were offered to public investors and it raised no capital through an issue.','The company completed its flotation by offering shares to public investors and raising capital.','未向公众发行股票不构成 flotation。'],[[1,'In mineral processing, flotation separates material by?',['making selected particles float','freezing every particle solid','sorting samples by their colour names only'],0,'flotation s1 可指利用浮力进行矿物分选。'],[2,'A company’s flotation usually involves?',['offering its shares to public investors for the first time','closing every share account permanently','moving its offices to a different floor'],0,'flotation s2 指公司首次公开发行股份。'],[1,'A flotation device helps a person?',['remain on the surface of water','sink more quickly','measure the water’s temperature'],0,'浮力装置帮助物体或人漂浮。'],[2,'Which event is a stock-market flotation?',['a private firm lists shares for public purchase','a listed company buys a life jacket','an investor sells one used bicycle'],0,'公司首次公开发行股票属于 flotation。']]);
P('flotilla','源自西班牙语 flotilla，是 flota“船队”的指小形式，指一起行动的一小队舰艇或民用船只。',[1,'海上救援','A flotilla of small rescue boats crossed the bay together, carrying food and blankets to villages cut off by the storm.','一支由小型救援船组成的船队一起穿过海湾，为被风暴隔绝的村庄运送食物和毯子。','A flotilla of small rescue boats crossed the bay together, / carrying food and blankets / to villages cut off by the storm.','可数名词；常见 a flotilla of boats/ships；强调一群船作为整体行动。','多艘小艇协同行动并运送物资，符合 flotilla。'],['The flotilla consisted of one person walking across the beach with no vessel or boat involved.','The rescue flotilla consisted of several small boats travelling together along the coast.','没有任何船只就不能称为船队 flotilla。'],[[1,'A flotilla is?',['a group of small vessels moving together','a single lighthouse on shore','a row of houses beside a river'],0,'flotilla 指一起行动的一队小船或舰艇。'],[1,'Which scene shows a flotilla?',['several fishing boats travel together to shelter','one sailor repairs a boat alone','a train carries passengers inland'],0,'多艘渔船一起航行构成 flotilla。'],[1,'Choose the usual construction.',['a flotilla of patrol boats','a flotilla at one sailor','flotilla to row a bicycle'],0,'常用 a flotilla of + 船只。'],[1,'A civilian flotilla might be organised for?',['a coordinated river cleanup with several boats','a solo walk through a museum','a flight of one airplane'],0,'多艘民用船只协同清理河道属于 flotilla。']]);
P('flounder','作为动词可能源自斯堪的纳维亚语系，词源细节不确定；可指在水、泥中笨拙挣扎，也可指慌乱失措。',[2,'研讨会','Asked to explain the unexplained results, the new analyst began to flounder, contradicting her earlier figures and losing track of the question.','被要求解释异常结果时，新分析员开始慌乱失措，既推翻先前数据，也忘了问题本身。','Asked to explain the unexplained results, / the new analyst began to flounder, / contradicting her earlier figures and losing track of the question.','s1 指在水、泥雪中笨拙扑腾；s2 比喻说话或行动混乱、没有清晰计划。','分析员答非所问、前后矛盾，体现 s2。'],['The swimmer floundered confidently across the pool with smooth strokes and never struggled to stay afloat.','The swimmer glided confidently across the pool with smooth strokes and never struggled to stay afloat.','顺畅轻松地游泳不叫 flounder；该词强调笨拙挣扎。'],[[2,'A manager who flounders during a crisis?',['acts in confusion without a clear plan','calmly follows a tested procedure','delegates each task with clear instructions'],0,'flounder s2 指慌乱失措。'],[1,'A person floundering in deep mud is?',['struggling clumsily to move','walking easily on dry ground','floating motionless on a boat'],0,'flounder s1 描写陷入泥中的笨拙挣扎。'],[2,'Which sentence uses flounder figuratively?',['He floundered when asked to explain the missing figures.','The seal floundered in shallow water.','The fish was served with rice.'],0,'被追问时答不上来是比喻义。'],[1,'Choose the natural phrase.',['flounder in the mud','flounder across a smooth floor with ease','flounder a clear speech'],0,'在泥中笨拙挣扎是自然搭配。']]);
P('flourishing','由 flourish 加 -ing 构成；flourish 经古法语源自拉丁语 florere“开花”，可表示繁荣成功或草木茂盛。',[1,'社区发展','The neighbourhood’s flourishing market now supports dozens of small businesses, and the council has kept the public square open for evening trade.','社区繁荣的集市如今支撑着数十家小商户，市议会也让公共广场在晚间继续开放经营。','The neighbourhood’s flourishing market now supports dozens of small businesses, / and the council has kept the public square open / for evening trade.','s1 指商业、文化或组织发展成功；s2 指草木茂盛健康地生长。','商户增加且市场活跃，体现商业繁荣 s1。'],['The flourishing orchard was dry and barren, with dead trees and no healthy growth anywhere.','The failing orchard was dry and barren, with dead trees and no healthy growth anywhere.','干枯荒芜的果园不能称为草木繁茂 flourishing。'],[[1,'A flourishing business is?',['growing and becoming successful','closing every branch','losing customers without recovery'],0,'flourishing s1 指繁荣发展。'],[2,'Flourishing plants are?',['growing thickly and healthily','wilting with no new leaves','made from metal'],0,'s2 描写草木茂盛生长。'],[1,'Which town has a flourishing arts scene?',['one with active galleries and many new performances','one where every arts venue has closed','one with no artists or audiences'],0,'活跃的画廊和演出反映文化繁荣。'],[2,'After steady rain, the garden is flourishing with?',['lush green growth','dry bare soil','broken glass'],0,'雨后茂盛的植物体现 s2。']]);
P('flourishment','由 flourish 加名词后缀 -ment 构成，表示持续成长、兴旺发展的状态；该词较少见，常用 flourishing 或 prosperity 替代。',[1,'社会史','The historian linked the town’s flourishment to its canal trade, which brought workshops, new residents, and steady investment over several decades.','历史学家把小镇的兴盛归因于运河贸易；数十年来，贸易带来了作坊、新居民和持续投资。','The historian linked the town’s flourishment to its canal trade, / which brought workshops, new residents, / and steady investment over several decades.','名词，较少用；描述繁荣发展的状态，flourishing/prosperity 更常见。','贸易带来人口、作坊与投资，体现城镇兴盛。'],['The town’s flourishment meant its businesses closed, residents left, and investment stopped for decades.','The town’s decline meant its businesses closed, residents left, and investment stopped for decades.','商户关闭、居民离开是衰退，不是 flourishment。'],[[1,'Flourishment refers to?',['a state of growing strongly and doing well','a sudden collapse in activity','a single flower placed in a vase'],0,'flourishment 表示兴盛发展的状态。'],[1,'Which evidence supports a town’s flourishment?',['new workshops open and the population grows','shops close and workers leave','the town loses its transport links'],0,'新作坊和人口增长表现发展兴旺。'],[1,'Which word is more common in everyday English?',['flourishing','flourishment','flourishmented'],0,'flourishment 较少见，flourishing 更常用。'],[1,'Choose the closest paraphrase.',['the flourishing of the regional economy','the disappearance of the regional economy','the measurement of a flower'],0,'flourishing 可表达经济兴盛。']]);
P('flout','源自中古英语 flouten“吹奏、吹嘘”等历史形式，现代指公然违抗规则，也可作名词表示公开蔑视。',[1,'交通法规','Several drivers flouted the temporary road closure by moving the barriers and entering the work zone despite warning signs.','尽管有警示标志，仍有几名司机移动路障并驶入施工区，公然违反临时封路规定。','Several drivers flouted the temporary road closure / by moving the barriers / and entering the work zone despite warning signs.','s1 为动词，常接 rule、law、ban；s2 为名词，指公开蔑视或挑衅行为。','司机明知封路仍闯入施工区，属于公然违抗。'],['The drivers flouted the closure by obeying every sign and turning away before they reached the work zone.','The drivers complied with the closure by obeying every sign and turning away before they reached the work zone.','遵守封路标志不是 flout；应改为 comply with。'],[[1,'To flout a safety rule is to?',['open defiance of it','follow it carefully','write it in a handbook'],0,'动词 flout 表示公然无视或违抗。'],[2,'A deliberate public flout of authority is?',['an open display of contempt','a private act of obedience','a neutral measurement'],0,'名词 flout 指公开蔑视行为。'],[1,'Which action flouts a ban?',['selling the prohibited item openly despite warnings','removing the item from sale','asking when the ban takes effect'],0,'明知禁令仍公开销售是违抗。'],[1,'Choose the correct construction.',['flout the regulations','flout at the regulations','flout to the regulations'],0,'flout 是及物动词，直接接被违抗规则。']]);
P('flowerbed','由 flower 与 bed 组成，指整理出的一片土壤区域，用来栽种花卉。',[1,'庭院设计','The gardener edged the flowerbed with bricks and planted drought-tolerant perennials so the path would stay clear through summer.','园丁用砖围住花坛并种上耐旱多年生植物，这样整个夏天小径都能保持畅通。','The gardener edged the flowerbed with bricks / and planted drought-tolerant perennials / so the path would stay clear through summer.','可数名词；常指庭院、公园或路边专门栽花的土地区域。','被砖围住并栽花的土地区域是 flowerbed。'],['The gardener called the paved parking bay a flowerbed although no soil or flowers were present there.','The gardener called the brick-edged patch of planted soil a flowerbed.','没有土壤或花卉的铺装车位不是花坛。'],[[1,'A flowerbed is?',['an area of soil where flowers are planted','a glass container for fish','a covered place to park a car'],0,'flowerbed 指种花的土地区域。'],[1,'Which feature belongs in a flowerbed?',['soil and planted blossoms','a row of car engines','a river channel'],0,'花坛中通常有土壤和花卉。'],[1,'Why might bricks edge a flowerbed?',['to define the planting area beside a path','to turn the flowers into stone','to measure rainfall'],0,'砖边可标出花坛与小径的界线。'],[1,'Choose the natural phrase.',['plant tulips in the flowerbed','swim across the flowerbed','park a train in the flowerbed'],0,'花坛中可以栽种郁金香。']]);
P('flowering','由 flower 加 -ing 构成，可作形容词指正在开花，也可作名词指开花过程或鼎盛时期。',[2,'文学史','The flowering of the city’s theatre movement came after local companies began staging original plays and touring them across the region.','当地剧团开始上演原创戏剧并在周边巡演后，这座城市的戏剧运动迎来了鼎盛时期。','The flowering of the city’s theatre movement / came after local companies began staging original plays / and touring them across the region.','s1 为形容词“开花的”；s2 名词可指开花过程，也可比喻某一活动的兴盛期。','戏剧运动迎来发展高潮，体现名词义 s2。'],['The flowering of the apple tree meant it produced no blossoms and had entered winter dormancy.','The dormancy of the apple tree meant it produced no blossoms and had entered winter rest.','没有花朵并进入冬季休眠不是 flowering。'],[[1,'A flowering plant is one that?',['is bearing flowers','has no roots','is made only of paper'],0,'形容词 flowering 表示正在开花或有花的。'],[2,'The flowering of a music scene is its?',['period of strongest development and success','permanent disappearance','list of concert ticket prices'],0,'flowering s2 可比喻某领域兴盛时期。'],[2,'“The flowering of modern science” refers to?',['a time when it developed and flourished','a garden where scientists grow roses','a period when research stopped'],0,'此处 flowering 比喻学科发展兴旺。'],[1,'Choose the natural phrase for a tree currently in bloom.',['a flowering cherry tree','a flowering yesterday','flowering of a red'],0,'flowering 可修饰 cherry tree，表示正在开花。']]);
P('flowery','由 flower 加形容词后缀 -y 构成，可指布满花朵，也可批评语言辞藻过多、过分华丽。',[2,'写作编辑','The editor removed the flowery descriptions from the witness statement so that the sequence of events would be easier to verify.','编辑删去了证人陈述中过度华丽的描写，使事件经过更容易核实。','The editor removed the flowery descriptions / from the witness statement / so that the sequence of events would be easier to verify.','s1 指布满花卉；s2 指语言修饰过多、过于华丽，常带批评意味。','编辑删繁就简是因为原描写辞藻过于华丽，体现 s2。'],['The flowery curtains were completely plain, with no flowers or decorative patterns anywhere on the fabric.','The plain curtains were completely undecorated, with no flowers or patterns on the fabric.','没有任何花饰的窗帘不属于 flowery。'],[[1,'A flowery dress is?',['decorated with many flowers','made from river water','written in a formal style'],0,'flowery s1 指布满花朵或花饰。'],[2,'Flowery prose is often?',['overly elaborate in its wording','a list of plain measurements','spoken without any words'],0,'flowery s2 指辞藻繁复、过于华丽。'],[2,'Why might an editor cut flowery language?',['it can obscure the main point with unnecessary ornament','it always contains no adjectives','it is written in a foreign alphabet'],0,'过度修饰可能遮蔽重点。'],[1,'Choose the natural phrase for wallpaper.',['a flowery pattern','a flowery beneath the floor','flowery very quietly'],0,'flowery 可修饰 pattern。']]);
P('flu','为 influenza 的缩略形式，指由流感病毒导致、可传染并常引起发热与全身酸痛的疾病；也可泛指相关病毒。',[1,'公共卫生','The school nurse sent a student home with suspected flu after fever and body aches developed during class.','一名学生上课时出现发热和全身酸痛后，校医怀疑是流感并让他回家休息。','The school nurse sent a student home with suspected flu / after fever and body aches developed / during class.','s1 指疾病，s2 指导致该病的一组病毒；日常用法多指 illness。','发热与全身酸痛是流感常见症状，体现疾病义。'],['The doctor called the patient’s fever “flu” even though there was no illness and the patient had no symptoms at all.','The doctor called the patient’s illness suspected flu because fever and body aches had appeared.','完全没有疾病或症状时，不应说患者得了 flu。'],[[1,'A person with the flu typically has?',['a contagious illness with symptoms such as fever and aches','a broken bone only','a permanent allergy to sunlight'],0,'flu s1 指流行性感冒疾病。'],[2,'In virology, flu can refer to?',['the group of viruses that cause influenza','a type of hospital bed','a vaccine appointment only'],0,'flu s2 可泛指导致流感的病毒。'],[1,'Which situation most strongly suggests flu?',['sudden fever, aches, and respiratory symptoms','a painless paper cut','a broken watch'],0,'发热、酸痛及呼吸道症状可能提示流感。'],[1,'“She is off school with flu” means?',['she is ill with influenza','she is learning to fly','she has moved to a new classroom'],0,'日常 flu 通常指患流感。']]);
P('fluctuation','源自拉丁语 fluctuare“起伏、波动”，与 fluctus“波浪”相关；可指数字价格的升降或情绪支持的变化。',[1,'外汇市场','The analyst tracked daily fluctuation in the exchange rate, noting each rise and fall before comparing the month’s average with last year’s.','分析员追踪汇率每日波动，记录每次涨跌，再把月均值与去年比较。','The analyst tracked daily fluctuation in the exchange rate, / noting each rise and fall / before comparing the month’s average with last year’s.','s1 常用于价格、利率、数值变化；s2 可描述感情、态度或支持度的起伏。','汇率反复涨跌属于 fluctuation 的数值义。'],['The exchange rate showed no fluctuation because it stayed exactly unchanged every day throughout the year.','The exchange rate remained stable because it stayed exactly unchanged every day throughout the year.','完全不变是稳定，不是波动。'],[[1,'A fluctuation in fuel prices is?',['a rise or fall over time','a fixed price with no change','a delivery delay'],0,'fluctuation s1 表示数值涨跌波动。'],[2,'A fluctuation in public support means?',['support rises and falls','support remains exactly constant','the public leaves the country'],0,'s2 可指态度或支持度不稳定地变化。'],[1,'Which graph shows fluctuation?',['a line that repeatedly rises and dips','a perfectly horizontal line','a list of unchanging names'],0,'曲线反复升降表现波动。'],[2,'Her fluctuation between confidence and doubt suggests?',['her feelings are unsteady','her opinion has never changed','she has no emotions'],0,'信心和怀疑交替体现情绪起伏。']]);
P('fluency','由 fluent 加 -cy 构成；fluent 源自拉丁语 fluere“流动”，比喻语言或技能运用顺畅自如。',[1,'语言学习','After a year of daily conversation practice, Mei’s fluency in Spanish improved enough for her to handle routine calls without long pauses.','经过一年每天练习对话，梅的西班牙语流利度提高了，现在可以应付日常电话而不必长时间停顿。','After a year of daily conversation practice, / Mei’s fluency in Spanish improved enough / for her to handle routine calls without long pauses.','不可数名词，可指语言流利或某项技能的熟练流畅；不必然代表所有语法都完美。','电话交流顺畅且停顿减少，体现语言 fluency。'],['The learner’s fluency improved when she could no longer form a sentence and paused after every word.','The learner’s fluency declined when she paused after every word and could not form a sentence.','逐字停顿且无法连贯表达说明流利度下降。'],[[1,'Language fluency is the ability to?',['use a language smoothly and accurately','memorise one isolated word only','speak loudly regardless of accuracy'],0,'fluency 指顺畅、较准确地使用语言。'],[1,'Which practice can improve fluency?',['regular conversation with feedback','avoiding all speaking practice','memorising punctuation without using the language'],0,'持续对话练习能提升表达流畅度。'],[1,'Does fluency mean a speaker never makes an error?',['No; it mainly concerns smooth and effective use.','Yes; it proves perfect knowledge of every word.','No; it means the person cannot understand speech.'],0,'流利不等于完全没有错误。'],[1,'Choose the natural phrase.',['fluency in French','fluency to arrive','fluency at the river bank'],0,'fluency in + 语言是常见搭配。']]);
P('fluently','由 fluent 加副词后缀 -ly 构成，表示说话或进行某项技能时顺畅自然、少有停顿。',[1,'求职面试','During the interview, the applicant answered fluently in English, explaining her experience without searching for words or losing her train of thought.','面试时，申请人用英语流畅回答，介绍经历时无需反复找词，也没有丢失思路。','During the interview, the applicant answered fluently in English, / explaining her experience / without searching for words or losing her train of thought.','副词，修饰 speak、read、answer 等；描述表达的流畅程度，而非音量或口音。','回答连贯、很少停顿，体现 fluently。'],['The applicant spoke fluently by stopping after every word and asking the interviewer to finish each sentence.','The applicant spoke haltingly by stopping after every word and asking the interviewer to finish each sentence.','频繁停顿、无法独立完成句子是断断续续 haltingly，不是 fluently。'],[[1,'To speak fluently is to speak?',['smoothly and without awkward pauses','only in a whisper','with no knowledge of the subject'],0,'fluently 表示说得流畅、少有不自然停顿。'],[1,'Which learner reads fluently?',['one who reads a passage smoothly and accurately','one who stops at every syllable','one who skips every line'],0,'顺畅而准确地朗读是 fluently。'],[1,'Fluently describes a person’s?',['manner of using language or a skill','height and weight','nationality alone'],0,'该副词修饰表达或技能运用方式。'],[1,'Choose the natural sentence.',['She speaks fluently in two languages.','She fluently the languages yesterday.','She speaks fluently to the grammar.'],0,'fluently 可修饰 speaks，后接语言。']]);
P('fluff','来源可能与模仿轻柔蓬松物的日耳曼语词形有关，现代名词指轻软的纤维绒屑；动词也可指把容易完成的任务弄糟。',[1,'家居清洁','The dryer filter was packed with fluff from the wool blankets, so Nia cleared it before running another load.','烘干机滤网里塞满了羊毛毯掉下的绒毛，妮娅清理后才继续烘干。','The dryer filter was packed with fluff from the wool blankets, / so Nia cleared it / before running another load.','s1 为轻软纤维或绒屑；s2 为动词，指把台词、射门或容易的任务搞砸。','滤网上的细软纤维属于 fluff s1。'],['The actor fluffed the simple line by delivering it perfectly on the first take without hesitation.','The actor delivered the simple line perfectly on the first take without hesitation.','一次顺利准确地说出台词不是 fluffed；fluff s2 指念错或搞砸。'],[[1,'A pillow filled with fluff contains?',['light, soft fibres','small stones','liquid metal'],0,'fluff s1 指蓬松轻软的纤维材料。'],[2,'An actor fluffs a line when the actor?',['forgets or misreads it','delivers it accurately','writes it down before rehearsal'],0,'fluff s2 指把本来容易的台词念错。'],[1,'Which sentence uses fluff as a noun?',['Dust and fluff collected beneath the sofa.','She fluffed the final shot.','He fluffed his lines on stage.'],0,'Dust and fluff 中 fluff 指绒屑。'],[2,'A footballer fluffed an easy shot by?',['missing it badly','scoring cleanly','passing it accurately'],0,'错失容易射门属于 fluffed an easy shot。']]);
P('fluffy','由 fluff 加形容词后缀 -y 构成，可指覆盖柔软细毛或质地轻松蓬松，也可贬指内容空洞。',[2,'媒体评论','The reviewer called the campaign speech fluffy because it offered cheerful slogans but no figures, deadlines, or workable steps.','评论者认为这篇竞选演讲内容空洞，因为它只有乐观口号，没有数据、期限或可行步骤。','The reviewer called the campaign speech fluffy / because it offered cheerful slogans / but no figures, deadlines, or workable steps.','s1 指柔软蓬松；s2 批评内容表面讨喜却缺乏实质信息。','只有口号而无计划，使演讲显得空洞，符合 fluffy s2。'],['The fluffy blanket was rough and stiff, with no soft fibres or airy texture at all.','The coarse blanket was rough and stiff, with no soft fibres or airy texture at all.','粗硬且无绒感的毯子不符合 fluffy 的质地义。'],[[1,'A fluffy kitten has?',['soft, light fur','scales made of stone','a completely hairless body'],0,'fluffy s1 指毛茸茸、蓬松的。'],[2,'A fluffy proposal may be criticised for being?',['pleasant-sounding but lacking serious detail','full of precise costs and deadlines','impossible to read because it is wet'],0,'fluffy s2 指听起来讨喜但缺少实质内容。'],[1,'Which object feels fluffy?',['a down-filled cushion','a sheet of steel','a glass marble'],0,'羽绒靠垫质地轻软蓬松。'],[2,'The report was called fluffy because it?',['avoided evidence and gave only vague promises','presented tested figures and clear steps','listed the full budget'],0,'缺乏证据和细节会使内容显得空洞。']]);
P('fluidity','由 fluid 加 -ity 构成；fluid 源自拉丁语 fluidus“流动的”，指容易流动的性质，也指动作或表达顺畅优雅。',[2,'舞蹈训练','The dancer’s fluidity across the stage came from months of balance practice, allowing each turn to flow naturally into the next.','舞者在舞台上的动作流畅优雅，源于数月平衡训练，因此每个旋转都自然衔接下一个动作。','The dancer’s fluidity across the stage / came from months of balance practice, / allowing each turn to flow naturally into the next.','s1 指物质的流动性；s2 指动作、语言或表现的流畅优雅。','舞步自然衔接，体现身体动作的 fluidity s2。'],['The liquid’s fluidity decreased when it became so thick that it would not flow through the narrow channel.','The liquid’s viscosity increased when it became so thick that it would not flow through the narrow channel.','无法流动说明流动性下降、黏度升高，不是 fluidity 增加。'],[[1,'A liquid’s fluidity describes how easily it?',['flows','keeps a sharp shape without moving','produces a sound'],0,'fluidity s1 是液体容易流动的性质。'],[2,'A speaker’s verbal fluidity is shown by?',['smooth, connected expression','long pauses after every word','unrelated answers'],0,'语言表达顺畅对应 fluidity s2。'],[1,'Which material has greater fluidity at room temperature?',['a thin oil that pours readily','a rigid block of stone','a dry wooden board'],0,'容易倾倒的油具有较高流动性。'],[2,'The gymnast’s fluidity impressed judges because?',['her movements linked smoothly and gracefully','she stopped between every movement','she remained motionless'],0,'动作连贯优雅是运动表现的流畅性。']]);
P('fluke','作为“侥幸”义的来源存在不同说法，现代用法强调偶然带来的意外成功；也可作动词表示侥幸做到。',[1,'体育竞赛','The underdog admitted that the winning shot was a fluke, since the ball bounced off the rim and dropped in by pure chance.','弱队承认那记制胜球纯属侥幸，因为球碰到篮圈后偶然弹进。','The underdog admitted that the winning shot was a fluke, / since the ball bounced off the rim / and dropped in by pure chance.','s1 为意外成功的名词；s2 为动词，指偶然成功。不要与 flounder 的鱼名混淆。','球意外反弹入筐，成功主要来自运气，符合 fluke。'],['The team’s repeatable winning strategy was called a fluke because it had been carefully practised and produced the same result in every trial.','The team’s single lucky win was called a fluke because it happened by chance.','经反复训练并稳定复现的策略不是偶然成功。'],[[1,'A fluke victory is one achieved?',['by unlikely good luck','through a guaranteed rule','after the match is cancelled'],0,'fluke s1 指靠运气偶然取胜。'],[2,'He fluked a difficult answer means he?',['got it right by chance','studied it carefully and knew it fully','refused to answer'],0,'动词 fluke 表示侥幸做成。'],[1,'Which result is most likely a fluke?',['a random bounce unexpectedly wins one game','a tested method succeeds in every trial','a team wins after a season of consistent play'],0,'一次随机弹跳带来的胜利最像偶然。'],[2,'She fluked the pass when?',['an accidental touch sent it to the target','she aimed carefully and repeated the technique','she chose not to pass'],0,'意外触球碰巧到位是侥幸完成。']]);
P('fluorescent','由 fluorescence 加形容词后缀 -ent 构成，指物质吸收能量时发出可见光，能量停止后发光也随之停止。',[1,'实验室','Under ultraviolet light, the dye produced a bright fluorescent glow, but it stopped shining as soon as the lamp was switched off.','紫外灯下，染料发出明亮的荧光；灯一关，光也随即消失。','Under ultraviolet light, the dye produced a bright fluorescent glow, / but it stopped shining / as soon as the lamp was switched off.','形容词，修饰 dye、lamp、light；荧光是受激发时发光，不等同持续储光的磷光。','停止照射后立即不再发光，符合 fluorescence 的特征。'],['The dye kept glowing for hours in total darkness after the excitation source had stopped, so the glow was called fluorescent.','The dye kept glowing for hours in darkness after excitation stopped, so the glow was described as phosphorescent.','持续余辉更接近磷光 phosphorescent；荧光通常随激发停止而停止。'],[[1,'A fluorescent material emits light while?',['it absorbs an energy source such as ultraviolet radiation','it is being cooled in darkness only','it loses all colour permanently'],0,'fluorescent 描述受激后发光。'],[1,'Which sign is likely fluorescent?',['one that glows under a UV inspection lamp','one that absorbs all light and remains invisible','one that produces only a low sound'],0,'紫外灯照射时发光符合 fluorescent。'],[1,'Fluorescent light usually stops when?',['the exciting energy source is removed','the room becomes quiet','the material is moved one centimetre'],0,'激发光源撤去后，荧光会很快停止。'],[1,'Choose the natural phrase.',['a fluorescent marker','fluorescent to walk','a fluorescent of the shelf'],0,'fluorescent 可作形容词修饰 marker。']]);
P('flux','源自拉丁语 fluxus“流动”，来自 fluere“流”；可指液体连续流动、持续变迁，也可作动词表示强热熔化。',[2,'技术转型','The department is in flux while two research units merge, so staff roles and reporting lines may change before the new structure is finalised.','两个研究部门合并期间，部门仍处于不断变化之中，因此员工职责和汇报关系可能在新架构定稿前调整。','The department is in flux while two research units merge, / so staff roles and reporting lines may change / before the new structure is finalised.','s1 指物质流动；s2 常用于 be in flux，表示情况不断变化；s3 为动词“加热熔化”。','职责和组织架构尚未稳定，体现 be in flux 的变化义。'],['The department was in flux because every role and reporting line had remained fixed for decades without any change.','The department was stable because every role and reporting line had remained fixed for decades without any change.','长期不变是 stable，不是处于变动中的 flux。'],[[2,'A society in flux is?',['undergoing continuing change','fixed in every respect','empty of people'],0,'flux s2 指不断变化、尚未定型的状态。'],[1,'In a pipe, flux may refer to?',['the continuous movement of liquid','a permanent legal contract','a written stage direction'],0,'flux s1 可指液体的持续流动。'],[3,'To flux a metal joint in this technical sense is to?',['heat it strongly so material melts or flows','freeze it without applying heat','measure its weight'],0,'flux s3 作动词可指通过加热使物质熔化。'],[2,'“Prices are in flux” means prices?',['keep changing and are not settled','remain exactly constant','have been removed from the market'],0,'in flux 表示处于持续变化中。']]);
P('flyby','由 fly 与 by 组成，指飞机或航天器不停留而近距离飞过某个目标。',[1,'太空探索','The probe’s flyby of Saturn’s moon lasted only minutes, but its cameras collected images of the icy surface before the spacecraft continued onward.','探测器飞越土星卫星只持续几分钟，但在继续前行前，摄像机拍下了冰质表面的图像。','The probe’s flyby of Saturn’s moon lasted only minutes, / but its cameras collected images / before the spacecraft continued onward.','可数名词；常接 of + 目标，强调近距离掠过，不进入轨道或停留。','航天器掠过目标后继续飞行，符合 flyby。'],['The spacecraft’s flyby of the moon lasted a year because it landed there and remained in orbit without moving past it.','The spacecraft’s landing on the moon lasted a year because it stayed there instead of flying past.','飞越是近距离经过且不停留；着陆并停驻不属于 flyby。'],[[1,'A spacecraft flyby involves?',['passing close to a target without stopping','landing and remaining on the surface','orbiting the target forever without passing it'],0,'flyby 指不停留的近距离飞过。'],[1,'Which is a flyby?',['an aircraft passes low over a landmark and continues its route','a plane parks at the airport overnight','a satellite stays fixed above one point'],0,'飞机近距离飞过目标而不停止是 flyby。'],[1,'A flyby can help scientists by?',['collecting observations during a brief close pass','guaranteeing a landing on the target','replacing all later measurements'],0,'近距离经过时可拍摄或采集数据。'],[1,'Choose the usual phrase.',['a flyby of the comet','a flyby at the comet without passing','flyby to remain on the surface'],0,'常用 a flyby of + 目标。']]);
P('flyover','由 fly 与 over 组成，可指道路立交桥，也可指飞机低空飞过地点的展示飞行。',[1,'道路工程','The new flyover carries northbound traffic above the railway crossing, reducing queues without closing the streets below.','新建的立交桥让北向车辆从铁路道口上方通过，减少排队，同时不封闭下方街道。','The new flyover carries northbound traffic above the railway crossing, / reducing queues / without closing the streets below.','s1 为道路上跨桥；s2 为飞机低空飞越的仪式性或展示飞行。','道路从铁路上方跨过，对应交通设施义 s1。'],['The highway flyover was a low aircraft display at a stadium, with no bridge or road crossing involved.','The stadium flyover was a low aircraft display above the crowd.','s1 不能指空中编队飞行；本句描述的是 s2。'],[[1,'In road engineering, a flyover is?',['a bridge carrying one road above another','a tunnel running beneath the sea','a railway signal'],0,'flyover s1 是道路立交桥。'],[2,'An air-show flyover is?',['aircraft passing low over a place as a display','a vehicle crossing a bridge','a pedestrian walking below a road'],0,'flyover s2 指飞机低空飞过展示。'],[1,'Which route uses a flyover bridge?',['traffic passes above a busy junction','cars stop at a level crossing','boats travel under a pier'],0,'立交桥让道路交通从交叉路口上方通过。'],[2,'A ceremonial flyover might feature?',['planes passing over a stadium during a public event','a bridge being painted','ships anchored in a harbour'],0,'公共仪式上飞机编队掠过是空中展示。']]);
P('flyspeck','由 fly 与 speck“斑点”组合而成，可指蝇粪留下的极小污点，也可指极微不足道的东西；动词指弄上小污点。',[1,'清洁检查','The conservator found a single flyspeck on the glass cover and removed it with a soft cloth before reopening the display.','修复人员在玻璃罩上发现一个极小的蝇粪斑点，重新开放展览前用软布将它擦去。','The conservator found a single flyspeck on the glass cover / and removed it with a soft cloth / before reopening the display.','s1 可数名词，指极小污点或微不足道之物；s2 作动词表示沾上细小斑点。','玻璃罩上的小污点是 flyspeck s1。'],['The restorer flyspecked the glass by polishing away every mark until its surface was completely spotless.','The restorer cleaned the glass by polishing away every mark until its surface was completely spotless.','擦掉所有污迹是清洁，不是弄上小污点。'],[[1,'A flyspeck on a painting is?',['a tiny spot of dirt','a large tear in the canvas','a frame hanging on the wall'],0,'flyspeck s1 指极小污点。'],[2,'To flyspeck a clean page is to?',['mark it with tiny spots','erase every mark','fold it neatly'],0,'动词 flyspeck 表示弄上细小污点。'],[1,'“The island was a flyspeck on the map” means it was?',['depicted as extremely small','the largest land mass shown','covered in flowers'],0,'比喻义表示微小得几乎不显眼。'],[2,'Which sentence uses flyspeck as a verb?',['Grease splashed and flyspecked the white cabinet.','A flyspeck fell from the cabinet.','The cabinet was repainted smoothly.'],0,'flyspecked 作动词表示沾上小点。']]);
P('flyway','由 fly 与 way 组成，指某一地区候鸟季节迁徙时沿用的广泛路线。',[1,'鸟类保护','Wetland reserves along the flyway provide resting and feeding sites for geese travelling between northern breeding grounds and southern wintering areas.','迁飞路线上的湿地保护区为在北方繁殖地与南方越冬地之间往返的大雁提供休息和觅食场所。','Wetland reserves along the flyway provide resting and feeding sites / for geese travelling between northern breeding grounds / and southern wintering areas.','可数名词；常指区域性候鸟路线，不是单只鸟的一次随机飞行。','保护区分布在候鸟季节迁徙通道沿线，体现 flyway。'],['The conservation map called a single bird’s circular flight inside its garden a major flyway used by an entire region.','The conservation map called the broad seasonal migration route used by regional bird populations a flyway.','一只鸟在花园里的短暂绕飞不是区域性迁飞路线。'],[[1,'A flyway is?',['a broad route used by migrating birds','a paved road reserved for aircraft','a cage where birds are kept'],0,'flyway 指候鸟的迁飞路径。'],[1,'Why protect wetlands along a flyway?',['migrating birds need places to rest and feed','the route must be hidden from all birds','wetlands prevent birds from moving'],0,'迁徙途中鸟类需要停歇和觅食地。'],[1,'A flyway connects?',['seasonal breeding and wintering areas','two classrooms in one school','a mountain summit to a road tunnel'],0,'迁飞路径连接季节性栖息地。'],[1,'Choose the natural phrase.',['birds migrate along a flyway','birds swim through a flyway underground','a flyway of pedestrian traffic'],0,'候鸟沿迁飞路线移动。']]);
P('focal','源自拉丁语 focus“炉火、焦点”，经科学用语发展为“焦点的”；也可表示最重要或最受关注的。',[1,'光学','The lens produced a sharp focal point on the sensor, allowing the camera to capture fine detail in the centre of the image.','镜头在传感器上形成清晰焦点，使相机捕捉到图像中心的细节。','The lens produced a sharp focal point on the sensor, / allowing the camera to capture fine detail / in the centre of the image.','形容词，s1 指光学焦点相关，也可指核心、中心地位；常与 point、issue 连用。','镜头将光线集中在传感器上的点，体现焦点义。'],['The focal issue was unimportant and received no attention, while every other topic dominated the meeting.','The peripheral issue was unimportant and received no attention, while other topics dominated the meeting.','不重要且无人关注的是边缘议题，不是 focal issue。'],[[1,'A focal point in a lens system is?',['the point where light rays are brought together','the camera’s battery compartment','the edge of a printed page'],0,'focal s1 与焦点相关。'],[1,'The focal issue of a meeting is?',['the central and most important topic','an unrelated minor detail','the meeting room’s floor colour'],0,'focal 也指最核心、最受关注的。'],[1,'Which is the focal concern in a safety review?',['the risk most central to the decision','a decorative choice unrelated to safety','the time the room was painted'],0,'核心风险是评估的 focal concern。'],[1,'Choose the natural phrase.',['a focal point','a focal at the lens','focal to be the room'],0,'focal point 是常见搭配。']]);
P('focalize','由 focal 加动词后缀 -ize 构成，表示使光线、精力或注意力汇聚于单一点。',[1,'研究设计','The team focalized its analysis on three measurable outcomes, keeping the survey short enough for participants to finish carefully.','团队把分析集中在三个可量化结果上，使问卷足够简短，参与者能够认真完成。','The team focalized its analysis on three measurable outcomes, / keeping the survey short enough / for participants to finish carefully.','及物动词；常用于理论、光学或学术表达，日常英语更常说 focus。','团队将分析集中于三个明确结果，体现 focalize。'],['The researcher focalized the study by adding twenty unrelated outcomes and dividing attention among every possible question.','The researcher broadened the study by adding unrelated outcomes and dividing attention among many questions.','把分析扩散到大量无关结果不是集中于一点。'],[[1,'To focalize attention is to?',['direct it toward a single point','scatter it across unrelated topics','remove it from the task'],0,'focalize 表示使注意力集中。'],[1,'Which action focalizes a study?',['limit the analysis to a few defined outcomes','add every imaginable question','avoid selecting any topic'],0,'限定少数明确结果使研究焦点集中。'],[1,'In optics, a lens focalizes rays by?',['bringing them together at a focus','spreading them randomly in all directions','absorbing every ray'],0,'透镜可使光线汇聚到焦点。'],[1,'Choose the natural construction.',['focalize effort on the main problem','focalize at the main problem','focalize to the effort'],0,'focalize effort on something 是自然结构。']]);
P('foetus','源自拉丁语 fetus“后代、生产”，英式拼写保留 oe；指哺乳动物胚胎期之后、出生之前的发育阶段。',[1,'产科','The scan showed that the foetus was growing normally, and the midwife discussed the next routine examination with the parents.','超声显示胎儿发育正常，助产士随后与父母讨论了下一次常规检查。','The scan showed that the foetus was growing normally, / and the midwife discussed / the next routine examination with the parents.','名词；英国及英联邦常写 foetus，美式通常写 fetus；生物学上处于胚胎期之后、出生之前。','超声检查的是出生前发育中的胎儿。'],['The nurse used foetus to describe a newborn who had already been delivered and was breathing outside the womb.','The nurse used newborn to describe a baby who had already been delivered and was breathing outside the womb.','出生后不再称为 foetus；newborn 指刚出生的婴儿。'],[[1,'A foetus is?',['a developing mammal before birth and after the embryonic stage','a fully grown adult animal','a newborn after delivery'],0,'foetus 指出生前特定发育阶段的哺乳动物。'],[1,'Which spelling is commonly used in British English?',['foetus','fetus only','foetalus'],0,'英式英语常用 foetus，美式常用 fetus。'],[1,'The foetal stage occurs?',['after the embryonic stage and before birth','after adulthood','only after an animal hatches from an egg'],0,'胎儿阶段在胚胎期之后、出生之前。'],[1,'A doctor discussing a foetus is discussing?',['prenatal development','a patient’s shoe size','a newborn’s first birthday'],0,'foetus 属产前发育语境。']]);
P('fogged','由 fog 加 -ed 构成，描述物体表面蒙上雾气，也可比喻记忆或思路被遮蔽。',[1,'驾驶安全','The cold car window fogged when the passengers breathed against it, so the driver waited until visibility returned before moving.','乘客朝冰冷车窗呼气后，玻璃起了雾；司机等视线恢复才启动车辆。','The cold car window fogged / when the passengers breathed against it, / so the driver waited until visibility returned before moving.','形容词或过去分词；可说 fogged glass/window，强调水汽使表面模糊。','车窗因呼气凝结而变得不透明，体现 fogged。'],['The window was fogged because it remained perfectly transparent and showed every detail without mist.','The window was clear because it remained perfectly transparent and showed every detail without mist.','完全透明、无雾的窗户应称 clear。'],[[1,'A fogged mirror is?',['covered with mist so the reflection is unclear','polished until perfectly transparent','broken into pieces'],0,'fogged 描述表面蒙雾而模糊。'],[1,'Why did the bathroom mirror fog?',['warm moist air condensed on its cooler surface','the mirror became a liquid','the room had no water vapour'],0,'水汽在冷表面凝结会使镜子起雾。'],[1,'“My memory was fogged” means the memory was?',['unclear or obscured','perfectly sharp and complete','painted blue'],0,'比喻义表示记忆或思路不清晰。'],[1,'Choose the natural phrase.',['a fogged-up windscreen','a fogged loudly yesterday','fogged to the window'],0,'fogged-up windscreen 表示起雾的挡风玻璃。']]);
P('foggy','由 fog 加 -y 构成，可指近地面被浓雾笼罩，也可比喻记忆或理解模糊。',[1,'航行','The harbour was foggy before dawn, and the captain delayed departure until the buoy lights and channel markers became visible.','黎明前港口大雾弥漫，船长等浮标灯和航道标志重新可见后才启航。','The harbour was foggy before dawn, / and the captain delayed departure / until the buoy lights and channel markers became visible.','s1 指有浓雾；s2 指记忆或理解不清楚。','航道标志被大雾遮蔽，体现天气义 s1。'],['The harbour was foggy because every buoy, ship, and shoreline was sharply visible through clear dry air.','The harbour was clear because every buoy, ship, and shoreline was sharply visible through dry air.','空气清澈且能清晰看见港口，不是 foggy。'],[[1,'A foggy morning has?',['thick low cloud that limits visibility','bright clear air with no mist','a sudden snowstorm in every case'],0,'foggy s1 指地面附近有浓雾。'],[2,'A foggy memory is?',['unclear or difficult to recall','perfectly detailed','a memory of clouds only'],0,'foggy s2 比喻记忆模糊。'],[1,'Which warning fits foggy conditions?',['use lights because visibility is reduced','turn off every navigation aid because visibility is perfect','expect the road to become dry immediately'],0,'大雾会降低能见度，需要开启灯光。'],[2,'“The details are still foggy to me” means?',['I do not understand or remember them clearly.','I can list every detail exactly.','I have never heard the language.'],0,'foggy 可比喻理解不清楚。']]);
P('foghorn','由 fog 与 horn 组成，指雾中发出声音以警示船只、帮助定位的号角或鸣笛装置。',[1,'海事安全','When visibility fell, the lighthouse sounded its foghorn at regular intervals so vessels could locate the coast and avoid the rocks.','能见度下降时，灯塔定时鸣响雾号，使船只辨认海岸位置并避开礁石。','When visibility fell, / the lighthouse sounded its foghorn at regular intervals / so vessels could locate the coast and avoid the rocks.','可数名词；传统上用于雾天海上警示，也可泛指声音很大的号角。','灯塔发声帮助船只定位，是 foghorn 的海事用途。'],['The lighthouse used its foghorn to make the coastline harder to locate by silencing every warning sound.','The lighthouse used its foghorn to warn vessels by sounding a loud signal in the fog.','雾号用于警示和帮助定位，不是让海岸更难找到。'],[[1,'A foghorn is sounded mainly to?',['warn ships and help them navigate in fog','signal the end of a football match','measure wind speed'],0,'雾号在雾中为船只提供声音信号。'],[1,'Which sound is a foghorn?',['a loud periodic blast from a coastal warning device','a quiet bell inside a kitchen','a bird singing in a forest'],0,'海岸警示装置定时发出的低沉鸣响是雾号。'],[1,'Why might ships listen for a foghorn?',['to estimate the location of a nearby coast or hazard','to learn the colour of a buoy','to receive a written weather report'],0,'声音可帮助船只判断海岸及危险物位置。'],[1,'Choose the natural phrase.',['sound the foghorn','foghorn the tide quietly','sound at foghorn the vessel'],0,'sound the foghorn 是自然搭配。']]);
P('foist','来源说法不一，现代英语常用结构 foist something on/upon someone，表示把对方不想要的东西或人硬塞给他。',[1,'消费权益','The vendor tried to foist an unwanted service plan on the customer by adding it to the bill without asking for consent.','商家未经同意便把顾客不想要的服务计划加到账单上，试图强行塞给顾客。','The vendor tried to foist an unwanted service plan on the customer / by adding it to the bill / without asking for consent.','及物动词；常用 foist something on/upon someone，含强加、硬塞的负面意味。','未经同意把服务计划塞到账单上，符合 foist。'],['The store foisted no unwanted warranty on the buyer because it clearly offered the optional plan and accepted the buyer’s refusal.','The store offered an optional warranty to the buyer and accepted the refusal.','清楚说明可选服务并接受拒绝，不是强加。'],[[1,'To foist an unwanted fee on a customer is to?',['impose it without the customer’s genuine agreement','remove it from the bill immediately','explain it and let the customer decline'],0,'foist 指把不想要的东西强加给别人。'],[1,'Which construction is standard?',['foist a charge on the buyer','foist a charge at the buyer','foist to charge the buyer'],0,'常用 foist something on someone。'],[1,'A manager foists a task on a colleague when the manager?',['forces an unwanted duty onto the colleague','asks whether the colleague is available','removes the task from the colleague’s list'],0,'强迫别人承担不愿意的任务符合 foist。'],[1,'Choose the closest paraphrase: “They foisted the outdated software on us.”',['They imposed the unwanted software on us.','They asked us to choose among updates.','They removed the old software for us.'],0,'foist 强调不受欢迎地硬塞给别人。']]);
P('folding','由 fold 加 -ing 构成的形容词，描述设计成可折平或折合、便于收纳的物品。',[1,'露营装备','The folding table fits into the car boot after its legs collapse beneath the top, leaving space for the family’s camping bags.','桌腿可以折到桌面下方，因此这张折叠桌能装进汽车后备箱，还能给露营包留出空间。','The folding table fits into the car boot / after its legs collapse beneath the top, / leaving space for the family’s camping bags.','形容词，可修饰 chair、table、screen；其结构可折叠收纳，不一定完全拆开。','桌腿折到桌面下方便于收纳，符合 folding。'],['The folding chair was a rigid one-piece block whose legs could not move or collapse for storage.','The fixed chair was a rigid one-piece block whose legs could not move or collapse for storage.','不能折叠收纳的刚性椅子不是 folding chair。'],[[1,'A folding chair is designed to?',['collapse into a smaller shape for storage','remain permanently fixed in one large piece','float above the ground'],0,'folding 表示可以折合收纳。'],[1,'Which object is folding?',['a portable stool whose legs tuck under its seat','a solid stone bench','a fixed concrete wall'],0,'可把腿折入座面下的凳子是折叠式。'],[1,'Why choose folding furniture for camping?',['it packs away compactly','it cannot be moved','it must be built into the ground'],0,'折叠后更便于携带和收纳。'],[1,'Choose the natural phrase.',['a folding screen','folding to the screen','a folding arrived quietly'],0,'folding 可修饰 screen。']]);
P('folkloric','由 folklore 加形容词后缀 -ic 构成，表示属于民间传说、口头传统或民俗文化的。',[1,'文化遗产','The museum’s folkloric collection includes regional legends, ritual songs, and embroidered costumes passed down through local families.','博物馆的民俗收藏包括地方传说、仪式歌曲，以及由当地家庭代代相传的刺绣服饰。','The museum’s folkloric collection includes regional legends, ritual songs, / and embroidered costumes / passed down through local families.','形容词，修饰 tale、tradition、music 等；强调民间文化传承，不是严格历史档案。','地方传说、歌曲和服饰均来自民间传统。'],['The folkloric account was a dated laboratory report supported by measurements and signed by the research team.','The scientific account was a dated laboratory report supported by measurements and signed by the research team.','实验室测量报告是科学记录，不是民间传说。'],[[1,'A folkloric tale is generally?',['a story belonging to a community’s oral tradition','a modern equipment manual','a list of laboratory readings'],0,'folkloric 指民间传说或传统相关。'],[1,'Which item is folkloric?',['a legend retold across generations in a region','a newly issued parking permit','a chemical formula in a lab notebook'],0,'代代口传的地方故事属于民俗传统。'],[1,'Folkloric music may be associated with?',['community customs and inherited performance','a machine’s repair schedule','a bank’s account balance'],0,'民间音乐常与社区习俗和传承表演相关。'],[1,'Choose the natural phrase.',['a folkloric legend','folkloric at the doorway','folkloric was yesterday'],0,'folkloric 可修饰 legend。']]);
P('folkway','由 folk 与 way 组合而成，社会学中指社群普遍遵循但通常不由法律强制的日常习俗。',[1,'社会学','In the village, removing shoes before entering a home is a folkway, and visitors are reminded of it politely rather than threatened with legal penalties.','在这个村庄，进屋前脱鞋是一种民间习俗；居民会礼貌提醒访客，而不是以法律处罚相威胁。','In the village, removing shoes before entering a home is a folkway, / and visitors are reminded of it politely / rather than threatened with legal penalties.','可数名词；指社区中被期待遵循的常规，通常靠社会习惯而非正式法律维持。','进门脱鞋靠礼貌提醒和社区期待维持，体现 folkway。'],['The community’s folkway was a criminal statute enforced by a court with mandatory prison sentences.','The community’s law was a criminal statute enforced by a court with mandatory penalties.','由法院强制执行的刑事法规是法律，而不是非正式 folkway。'],[[1,'A folkway is?',['a customary behaviour a community expects but does not usually enforce by law','a written criminal code','an individual’s private invention'],0,'folkway 指不由法律强制的社区习俗。'],[1,'Which is most likely a folkway?',['greeting neighbours in a customary way','paying a tax required by statute','obtaining a legally required licence'],0,'日常问候方式通常由习俗而非法律维持。'],[1,'What may happen if someone ignores a folkway?',['others may disapprove socially','a court must always impose prison','the custom becomes a traffic signal'],0,'违反习俗可能招致社会不赞同，但通常不属违法。'],[1,'Choose the best distinction.',['A folkway is a social custom; a law is formally enforceable.','A folkway is always a written statute.','A law is merely a private preference.'],0,'folkway 与法律的区别在于后者可正式强制执行。']]);
P('folly','由 fool 加名词后缀 -y 构成，表示缺乏判断力，也可指由此做出的荒唐举动。',[1,'公共工程','The council admitted it was folly to build the footbridge without testing the riverbanks, which collapsed during the first heavy rain.','市议会承认未检查河岸就修建步行桥是愚蠢之举；第一场大雨便冲垮了河岸。','The council admitted it was folly to build the footbridge without testing the riverbanks, / which collapsed / during the first heavy rain.','不可数性质名词，也可指具体荒唐行为；常见 it is folly to do something。','未评估河岸便施工导致坍塌，体现判断失当。'],['The engineer called it folly to test the riverbank first, because careful checks had prevented every failure.','The engineer called it prudent to test the riverbank first, because careful checks had prevented failure.','先检查并避免事故是审慎之举，不是 folly。'],[[1,'It is folly to ignore a clear evacuation warning means?',['doing so would be foolish','doing so would be legally required','the warning is a musical instrument'],0,'folly 指缺乏智慧或荒唐的举动。'],[1,'Which action is most clearly folly?',['removing a safety rail before inspecting a high platform','checking the rail before use','closing the platform during repairs'],0,'在高处平台未检查前拆掉护栏是愚蠢冒险。'],[1,'Folly is closest in meaning to?',['foolishness','patience','accuracy'],0,'folly 表示愚蠢。'],[1,'Choose the natural construction.',['It was folly to skip the inspection.','It was folly at the inspection.','Folly it was the inspection to.'],0,'常说 it is folly to do something。']]);
P('foment','源自拉丁语 fomentare“温暖、加热”，进入英语后常指故意煽动怒气或动乱；旧义也指用温湿布热敷。',[1,'政治动乱','The group spread false rumours to foment unrest in the district, hoping angry crowds would block the council’s emergency meeting.','该组织散布谣言，企图煽动当地动乱，盼望愤怒的人群阻止市议会召开紧急会议。','The group spread false rumours to foment unrest in the district, / hoping angry crowds would block / the council’s emergency meeting.','s1 为现代常用动词义“煽动”；s2 为旧用法，指用温湿布敷痛处。','散布谣言以激起动乱，符合 foment s1。'],['The organisers fomented calm by discouraging rumours, resolving disputes, and asking the crowd to remain peaceful.','The organisers fostered calm by discouraging rumours, resolving disputes, and asking the crowd to remain peaceful.','劝止谣言并维持和平是平息事态，不是煽动动乱。'],[[1,'To foment rebellion is to?',['deliberately stir it up','quietly prevent it','write a history of it'],0,'foment s1 指故意煽动叛乱。'],[2,'In an old medical text, to foment a sore meant to?',['apply a warm, moist cloth to it','remove it with a sharp tool','cover it with dry ice'],0,'foment s2 是旧义“热敷”。'],[1,'Which action could foment public anger?',['spreading a false accusation to provoke a crowd','correcting the rumour and opening a dialogue','providing a clear emergency update'],0,'故意传播虚假指控以激怒公众属于煽动。'],[1,'Choose the common modern phrase.',['foment unrest','foment at the crowd','foment to the law'],0,'foment unrest 是常见搭配。']]);
P('foodstuff','由 food 与 stuff 组成，统称可供人或动物食用的物质；也可具体指用于制食品的农产品原料。',[1,'救灾物资','The relief centre checked every foodstuff for damage before distributing safe supplies to families displaced by the flood.','救援中心在把安全物资发给洪灾流离失所的家庭前，逐项检查所有食品。','The relief centre checked every foodstuff for damage / before distributing safe supplies / to families displaced by the flood.','可数或集合用法；s1 泛指食用品，s2 常指谷物等食品原料。','救援中心检查待分发的食物，体现 foodstuff s1。'],['The mill classified wheat as a finished meal rather than a foodstuff used to make flour.','The mill classified wheat as a foodstuff used to make flour.','小麦是制粉原料，属于 foodstuff，而不是已经制好的餐食。'],[[1,'Foodstuffs are?',['substances eaten by people or animals','tools used only for farming','clothes worn during cooking'],0,'foodstuff s1 指作为食物的物质。'],[2,'Wheat sold to a mill for making bread is a?',['foodstuff used as a food ingredient','finished loaf of bread','non-food machine part'],0,'谷物可作为制食品的原料。'],[1,'Which item is a foodstuff?',['dried beans for cooking','a steel cooking pan','a paper shopping bag'],0,'豆类本身是可食用物质。'],[2,'A shortage of grain foodstuffs could affect?',['the supply of ingredients used to make food','the supply of car tyres','the colour of a harbour'],0,'粮食原料短缺会影响食品生产。']]);
P('footage','由 foot 的长度单位与后缀 -age 构成，现代常指拍摄并记录下来的电影或视频素材。',[1,'新闻报道','The newsroom reviewed the security-camera footage before publishing its report, checking the timestamps against the shop’s written account.','新闻编辑部在发布报道前查看了监控录像，并把时间戳与商店的书面说明核对。','The newsroom reviewed the security-camera footage / before publishing its report, / checking the timestamps against the shop’s written account.','不可数名词；常用 video、camera、archival footage，指影像记录而非单张照片。','编辑部核对监控动态影像，符合 footage。'],['The editor called a single still photograph twenty minutes of footage even though no video had been recorded.','The editor called the still photograph a frame from footage only if it came from recorded video.','未录制视频的单张照片不是 footage。'],[[1,'Security-camera footage is?',['recorded video of events','a written witness statement only','a map of the camera’s location'],0,'footage 指拍摄记录的影像资料。'],[1,'Why might a reporter review footage?',['to see what a camera recorded','to calculate the weight of the camera','to hear a radio forecast'],0,'查看录像可核对事件经过。'],[1,'Which is a natural phrase?',['archival footage of the ceremony','footage of a printed paragraph only','footage to arrive late'],0,'archival footage 是常见搭配。'],[1,'Footage usually refers to?',['moving-image material recorded on film or video','a shoe size','a page number in a book'],0,'现代 footage 常指电影或视频素材。']]);
P('foothill','由 foot 与 hill 组成，指较高山脉下部坡地上的低矮山丘。',[1,'地形测绘','The village lies among the foothills below the main range, where small streams descend toward the broad valley.','村庄坐落在主山脉下方的山麓丘陵间，小溪从那里流向宽阔山谷。','The village lies among the foothills below the main range, / where small streams descend / toward the broad valley.','可数名词，常用复数 foothills；位于较大山脉下部，不等于山顶或山麓平原。','村庄所在的低丘位于主山脉下方，符合 foothills。'],['The survey map labelled the highest peak above the tree line a foothill at the bottom of the mountain range.','The survey map labelled the low hills at the base of the range foothills.','高耸主峰不是山脉下部的低丘。'],[[1,'Foothills are?',['low hills along the lower slopes of a larger range','the highest peaks in a mountain chain','flat land under the sea'],0,'foothill 指大山脉下方的低丘。'],[1,'A town in the foothills is likely?',['near the base of a mountain range','on a distant ocean island','inside a deep underground cave'],0,'foothills 位于山脉的低处。'],[1,'Which landscape has foothills?',['rolling low hills rising toward a high mountain range','a level plain hundreds of miles from mountains','a sheer peak with no lower slopes'],0,'由低丘过渡到高山的地形符合 foothill。'],[1,'Choose the natural phrase.',['the Himalayan foothills','foothills above every summit','a foothill of a river boat'],0,'山脉名称前可用 foothills。']]);
P('footnote','由 foot 与 note 组成，指印在页面底部、补充说明正文的注释。',[1,'学术写作','A footnote at the bottom of the page identifies the archive that supplied the letter and explains the editor’s dating method.','页面底部的脚注注明信件来源档案，并解释编辑采用的断代方法。','A footnote at the bottom of the page / identifies the archive that supplied the letter / and explains the editor’s dating method.','可数名词；通常以编号与正文对应，置于页面底部，区别于文末注释。','页面下方补充来源和方法信息，是 footnote。'],['The book’s footnote appeared in the middle of the paragraph and replaced the entire main text.','The book’s footnote appeared at the bottom of the page and added a brief source comment.','脚注位于页面底部并补充正文，不是替代正文的段落。'],[[1,'A footnote usually appears?',['at the bottom of a page','on the cover only','inside the book’s spine'],0,'footnote 的位置通常在页面底部。'],[1,'Why add a footnote to a research paper?',['to provide a comment or source detail linked to the text','to replace the conclusion with a picture','to hide the title'],0,'脚注补充正文说明或来源信息。'],[1,'A numbered footnote is linked to?',['a point in the main text','the book’s shipping label','a random page with no reference'],0,'编号将脚注与正文对应位置关联。'],[1,'Choose the natural phrase.',['refer to a footnote','refer footnote at from','a footnote above the roof'],0,'refer to a footnote 是自然表达。']]);
P('forage','源自古法语 forage“饲料、觅食”，词义发展为搜寻食物、强行征集粮草，也可作名词指牲畜饲料。',[1,'野生动物','At dusk, the badgers forage across the meadow for beetles and fallen fruit before returning to their setts.','黄昏时，獾在草地上四处觅食甲虫和落果，然后回到洞穴。','At dusk, the badgers forage across the meadow / for beetles and fallen fruit / before returning to their setts.','s1 动词指四处搜寻食物；s2 指强行征集粮草；s3 名词指马或农场动物的饲料。','獾在草地上寻找甲虫和果实，体现 forage s1。'],['The army foraged supplies peacefully from willing local merchants who donated food without pressure.','The army purchased supplies peacefully from willing local merchants who donated food without pressure.','自愿捐赠并和平购买不是强行征集粮草的 forage s2。'],[[1,'When birds forage, they?',['search an area for food','build a courtroom','sleep through the entire year'],0,'forage s1 指动物四处寻找食物。'],[2,'An army foraged grain from nearby farms when it?',['took food and supplies from the area by force','paid market prices to willing sellers','planted a new crop for local farmers'],0,'forage s2 指军队强行征集粮草。'],[3,'Farmers store forage for?',['horses and other livestock to eat','use as a courtroom document','fuel for a camera'],0,'forage s3 指牲畜饲料。'],[1,'A raccoon foraging in a bin is?',['searching for food','measuring the bin','training to pull a cart'],0,'浣熊在垃圾桶里找食物是觅食。']]);
P('forager','由 forage 加施事后缀 -er 构成，可指搜寻食物的动物，也可指靠狩猎和采集野生食物生活的人。',[2,'史前考古','The archaeologists found stone tools and charred seeds at the campsite, evidence that the group had lived as foragers rather than farmers.','考古学家在营地发现石器和烧焦的种子，说明这群人靠采集和狩猎生活，而非务农。','The archaeologists found stone tools and charred seeds / at the campsite, / evidence that the group had lived as foragers rather than farmers.','s1 指觅食动物；s2 指以狩猎采集为生的人群成员。','工具和种子显示人类群体采集野食，体现 forager s2。'],['The forager was a wheat farmer who relied entirely on cultivated fields and never hunted or gathered wild food.','The farmer was a wheat grower who relied on cultivated fields rather than hunting or gathering wild food.','完全依赖耕种、从不狩猎采集的人是 farmer，不是狩猎采集者。'],[[1,'An animal forager is one that?',['moves around to find food','guards a courtroom','builds a bridge'],0,'forager s1 指四处觅食的动物。'],[2,'A human forager traditionally obtains food by?',['hunting and gathering wild resources','relying only on industrial farming','purchasing all meals in a supermarket'],0,'forager s2 指狩猎采集者。'],[1,'Which creature is acting as a forager?',['a squirrel searching for nuts','a sleeping cat indoors','a stone statue in a garden'],0,'松鼠寻找坚果是在觅食。'],[2,'A prehistoric forager’s group would most likely?',['collect wild plants and hunt animals','grow only wheat in fenced fields','import packaged meals by rail'],0,'采集野生植物和狩猎是传统生计方式。']]);
P('foray','源于中古英语及古法语相关词形，原指突然袭击；现代也指短暂涉足自己不熟悉的活动。',[2,'跨界尝试','The architect made a brief foray into documentary filmmaking, directing one short film about the restoration of an abandoned station.','这位建筑师短暂涉足纪录片拍摄，执导了一部关于修复废弃车站的短片。','The architect made a brief foray into documentary filmmaking, / directing one short film / about the restoration of an abandoned station.','s1 为短促袭击后撤退；s2 指短暂尝试新领域，常用 a foray into。','建筑师暂时尝试电影制作，体现 s2。'],['The army’s foray into enemy territory was a decade-long peaceful residence with no attack and no withdrawal.','The army’s occupation of the territory was a decade-long presence without a brief raid.','长期驻留而非短促袭击不属于 foray s1。'],[[2,'A first foray into acting is?',['a brief attempt to enter a new activity','a lifelong career with no first step','a formal retreat from the stage'],0,'foray s2 指短暂涉足新领域。'],[1,'A military foray is usually?',['a brief attack into enemy territory followed by withdrawal','a permanent peaceful border agreement','a routine trip to a local shop'],0,'foray s1 指短促袭击后撤离。'],[2,'Which sentence uses foray figuratively?',['The scientist made a foray into public radio.','The patrol made a quick foray across the border.','The soldiers withdrew after the raid.'],0,'科学家短暂尝试广播工作是比喻义。'],[2,'Choose the common phrase.',['a foray into journalism','a foray at staying forever','foray to the newspaper the desk'],0,'a foray into + 领域是常见结构。']]);
P('forbearance','由 forbear 加 -ance 构成，forbear 与古英语 forberan“克制、忍耐”相关，指耐心自制或暂缓行使权利。',[1,'债务协商','The lender showed forbearance by delaying collection for two months while the family arranged a realistic repayment schedule.','贷款方表现出宽容，在家庭制定可行的还款计划时，将催收暂缓了两个月。','The lender showed forbearance / by delaying collection for two months / while the family arranged a realistic repayment schedule.','不可数名词；在法律或金融语境中可指暂缓执行权利，也可指耐心宽容。','贷款方暂缓催收，体现 forbearance。'],['The lender showed forbearance by refusing every extension and immediately seizing the family’s home.','The lender showed no forbearance by refusing every extension and immediately seizing the family’s home.','立即强制收回房屋且拒绝宽限，说明缺少 forbearance。'],[[1,'Forbearance means?',['patience or restraint, sometimes delaying enforcement of a right','a sudden aggressive attack','a signed meal receipt'],0,'forbearance 指宽容、自制或暂缓执行。'],[1,'A bank grants forbearance when it?',['temporarily delays collection under agreed conditions','forgives every debt automatically','refuses to discuss payment dates'],0,'暂缓催收是金融语境中的 forbearance。'],[1,'Which behaviour shows forbearance?',['waiting calmly while another person explains a mistake','punishing someone before hearing any facts','interrupting every sentence'],0,'耐心等候对方解释体现宽容。'],[1,'Choose the natural phrase.',['show forbearance toward a debtor','forbearance at to collect','forbearance the courtroom yesterday'],0,'show forbearance 是自然搭配。']]);
P('forbidding','由 forbid 加 -ing 构成形容词，表示外表严峻、令人望而却步的。',[1,'建筑观感','The fortress looked forbidding from the valley, with dark stone walls and narrow windows that made the entrance seem difficult to approach.','从山谷望去，堡垒显得阴森严峻；深色石墙和狭窄窗户让入口令人不敢靠近。','The fortress looked forbidding from the valley, / with dark stone walls and narrow windows / that made the entrance seem difficult to approach.','形容词，常修饰 appearance、expression、landscape；描述令人畏惧或不愿接近的外观。','堡垒外观让人望而却步，符合 forbidding。'],['The forbidding entrance welcomed visitors warmly with bright flowers, open doors, and friendly signs.','The inviting entrance welcomed visitors warmly with bright flowers, open doors, and friendly signs.','鲜花、敞门和友好标志营造欢迎感，与 forbidding 相反。'],[[1,'A forbidding building appears?',['stern or threatening and difficult to approach','warmly welcoming','small and made of cloth'],0,'forbidding 表示外观严峻、令人畏惧。'],[1,'Which expression is forbidding?',['a cold stare that makes visitors hesitate','a cheerful smile inviting people inside','a neutral label on a box'],0,'冷峻目光令人不敢接近。'],[1,'The forbidding cliffs discouraged climbers because they looked?',['dangerous and imposing','soft and easy to climb','painted with flowers'],0,'险峻外观可能令攀登者退却。'],[1,'Choose the natural phrase.',['a forbidding appearance','a forbidding to welcome','forbidding at breakfast loudly'],0,'forbidding 可修饰 appearance。']]);
P('forcible','由 force 加 -ible 构成，可指违背抵抗而使用武力，也可形容论证有力、有效。',[2,'辩论写作','Her forcible argument persuaded the board because it connected each recommendation to documented costs and measurable public benefits.','她的论证有力，说服了董事会，因为每项建议都与有据可查的成本和可衡量的公共利益相联系。','Her forcible argument persuaded the board / because it connected each recommendation / to documented costs and measurable public benefits.','s1 指以武力强迫；s2 指理由或表达强劲有说服力。','论据有证据支持并成功说服董事会，体现 s2。'],['The forcible removal was voluntary because everyone agreed freely and no resistance or pressure occurred.','The consensual removal was voluntary because everyone agreed freely and no resistance or pressure occurred.','自愿同意且无强迫不是 forcible s1。'],[[1,'A forcible eviction involves?',['using force against resistance','a tenant leaving voluntarily','a written invitation to stay'],0,'forcible s1 指使用强力、违背抵抗。'],[2,'A forcible argument is?',['strong and persuasive','weak and unrelated','delivered only by shouting'],0,'s2 描述论点有力，不是身体暴力。'],[1,'Which action is forcible?',['removing someone physically despite their resistance','asking someone to leave and receiving agreement','sending a polite reminder'],0,'违背抵抗而强制移除属于 s1。'],[2,'Why was the case for repairs forcible?',['it used strong evidence and clear reasoning','it threatened the audience physically','it omitted every relevant fact'],0,'有力证据与推理使论证令人信服。']]);
P('ford','源自古英语 ford，指河流中可步行或涉水通过的浅处；也可作动词表示从浅滩涉水而过。',[1,'徒步旅行','At the marked ford, hikers crossed the stream one at a time, using the shallow gravel bed instead of the flooded footbridge.','徒步者在标记浅滩处逐个过溪，走较浅的砾石河床，而没有走被洪水淹没的便桥。','At the marked ford, hikers crossed the stream one at a time, / using the shallow gravel bed / instead of the flooded footbridge.','s1 为名词“浅滩”；s2 为动词“涉水渡过”。过浅滩前需评估水流与深度。','砾石浅水处可供徒步者渡溪，符合名词义 ford。'],['The hikers chose a ford because the river was too deep to cross there and no shallow passage existed.','The hikers chose a bridge because the river was too deep to cross at any ford.','深水无浅滩不能称 ford；此时应走桥。'],[[1,'A river ford is?',['a shallow place where people can cross','the deepest part of a lake','a bridge high above the water'],0,'ford s1 指可涉水通过的河流浅处。'],[2,'To ford a stream is to?',['cross it at a shallow place','build a dam across it','measure its fish population'],0,'ford s2 作动词意为涉水过河。'],[1,'Which map symbol might mark a ford?',['a safe shallow crossing point','a mountain summit','a railway station'],0,'地图可能标出可渡河的浅滩。'],[2,'The riders forded the river by?',['leading their horses through the shallow crossing','using a ferry without entering the water','climbing a nearby tree'],0,'马匹从浅处涉水渡河是 forded。']]);
P('fore','源自古英语 fore“前方”，可作副词表示在前面或朝船头方向，也可作形容词表示位于前部。',[1,'航海','The engineer moved to the fore of the vessel to inspect the anchor chain, while the crew remained near the stern.','工程师走到船头检查锚链，船员则留在船尾附近。','The engineer moved to the fore of the vessel / to inspect the anchor chain, / while the crew remained near the stern.','s1 常见于 to the fore 或航海“朝船头”；s2 作定语表示位于前部。','与 stern“船尾”相对，工程师朝船头移动，体现 fore s1。'],['The fore section of the ship was at the stern beside the propeller, not near the bow.','The aft section of the ship was at the stern beside the propeller, not near the bow.','船尾属于 aft，不是 fore。'],[[1,'To move to the fore of a ship is to move?',['toward its bow or front','toward its stern only','below the waterline'],0,'fore s1 指船的前方或船头方向。'],[2,'The fore cabin is situated?',['at the front of the vessel','at the rear behind the stern','under the sea'],0,'fore s2 作形容词表示位于前部。'],[1,'Which word contrasts with the fore of a ship?',['aft','aboard','afloat'],0,'aft 表示船尾方向，与 fore 对应。'],[2,'Choose the natural phrase.',['the fore part of the aircraft','fore behind the engine at the rear','the fore below the keel'],0,'fore 可作形容词修饰 part。']]);
P('forebear','由 fore 与 bear 的古义“出生、产生”组合而成，指较早一代的祖先。',[1,'家族史','The family’s forebears migrated north generations ago, and the local archive still holds the land records they signed.','这个家族的祖先几代以前迁往北方，当地档案仍保存着他们签署的土地记录。','The family’s forebears migrated north generations ago, / and the local archive still holds / the land records they signed.','可数名词；常用复数 forebears，语气较正式，指早于父母辈的祖先。','几代以前迁徙并留下记录的人属于 forebears。'],['Her forebear was the baby she would give birth to next year, not a relative from an earlier generation.','Her descendant was the baby she would give birth to next year, not an ancestor from an earlier generation.','未来出生的后代是 descendant，不是过去的祖先 forebear。'],[[1,'A person’s forebears are?',['ancestors from earlier generations','children who may be born in the future','colleagues at the same workplace'],0,'forebear 指过去世代的祖先。'],[1,'Which record might mention forebears?',['a family archive tracing great-grandparents','a forecast for next week’s weather','a current restaurant menu'],0,'家族档案会记录祖先信息。'],[1,'Forebear is closest in meaning to?',['ancestor','descendant','neighbour'],0,'forebear 与 ancestor 同义。'],[1,'Choose the natural phrase.',['the customs of our forebears','the forebear of tomorrow’s child','forebear at the meeting'],0,'customs of our forebears 指祖先的习俗。']]);
P('forecaster','由 forecast 加施事后缀 -er 构成，指以判断并发布未来可能状况为工作的人。',[1,'气象服务','The forecaster warned coastal residents about high winds before the storm reached the harbour, giving them time to secure boats and windows.','风暴抵达港口前，预报员提醒沿海居民注意强风，让他们有时间固定船只和窗户。','The forecaster warned coastal residents about high winds / before the storm reached the harbour, / giving them time to secure boats and windows.','可数名词；常指天气预报员，也可泛指经济或市场预测者。','预测风暴并发布警报的人是 forecaster。'],['The forecaster described yesterday’s weather after it had happened and made no prediction about future conditions.','The reporter described yesterday’s weather after it had happened and made no prediction about future conditions.','只报道已发生的天气不是预测未来的工作。'],[[1,'A weather forecaster tries to?',['predict likely future weather','measure the height of a mountain only','repair a ship’s engine'],0,'forecaster 指预测未来情况的人。'],[1,'An economic forecaster may estimate?',['future prices or growth','the exact colour of a past painting','the depth of a river crossing'],0,'经济预测者会预测价格或增长。'],[1,'Which person is a forecaster?',['a meteorologist issuing tomorrow’s rain outlook','a witness describing yesterday’s event','a mechanic replacing a tyre'],0,'发布未来天气展望的人是 forecaster。'],[1,'Choose the natural phrase.',['a forecaster predicts heavy rain','a forecaster repairs the rain','a forecasted of the person'],0,'forecaster 常与 predicts weather 等搭配。']]);
P('foreground','由 fore 与 ground 组成，指画面中离观察者最近的部分，也可指最受关注的位置。',[1,'摄影构图','The photographer placed a branch in the foreground to frame the distant lighthouse and give the image a stronger sense of depth.','摄影师把一根树枝放在前景中，衬托远处灯塔并增强画面的纵深感。','The photographer placed a branch in the foreground / to frame the distant lighthouse / and give the image a stronger sense of depth.','s1 为画面近处部分；s2 可指注意力或讨论中最显著的位置。','离镜头最近的树枝属于图像前景。'],['The boat at the very back of the photograph was placed in the foreground, while nearby flowers filled the distant background.','The boat at the very back of the photograph was placed in the background, while nearby flowers filled the foreground.','画面远处是 background，近处花朵是 foreground。'],[[1,'The foreground of a photograph is?',['the area closest to the viewer','the most distant horizon only','the camera’s battery compartment'],0,'foreground s1 指画面近处。'],[2,'To bring housing costs to the foreground means to?',['make them a central public concern','hide them from discussion','move a building physically forward'],0,'比喻义 s2 指把某事置于关注中心。'],[1,'Which object is in the foreground?',['a cup close to the camera','a mountain on the far horizon','a cloud behind the mountain'],0,'离观察者较近的杯子位于前景。'],[2,'A report foregrounds safety by?',['giving safety issues the most prominent attention','burying them in an appendix','omitting them entirely'],0,'foreground 作动词或相关表达指突出、强调。']]);
P('foreigner','由 foreign 加名词后缀 -er 构成，指来自另一个国家的人；具体语气应结合语境，避免把国籍当作负面标签。',[1,'边境检查','The officer directed each foreigner to the correct immigration desk and provided translated instructions about the entry forms.','工作人员把每位外国人引导到正确的移民柜台，并提供入境表格的翻译说明。','The officer directed each foreigner to the correct immigration desk / and provided translated instructions / about the entry forms.','可数名词；指来自他国的人，正式场合可根据制度使用 visitor、international student 等更具体说法。','来自其他国家并办理入境手续的人符合 foreigner。'],['The form called a citizen a foreigner merely because the citizen had crossed into another street in the same town.','The form called a visiting national a foreigner because the person came from another country.','换到同城另一条街不改变国籍；foreigner 指来自另一国家的人。'],[[1,'A foreigner is someone who?',['comes from another country','moves to another street in the same town','changes jobs in the same office'],0,'foreigner 指来自别国的人。'],[1,'A country’s visitor may be called a foreigner because?',['the visitor is from another nation','the visitor entered a different room','the visitor speaks loudly'],0,'国籍来源不同是 foreigner 的定义依据。'],[1,'Which context uses foreigner accurately?',['an immigration guide explains entry rules to people from other countries','a local resident walks across a town square','a colleague changes desks'],0,'移民手续针对来自其他国家的访客。'],[1,'A more specific, neutral term for someone studying abroad could be?',['international student','forebear','foreleg'],0,'按具体身份称 international student 更清楚。']]);
P('foreland','由 fore 与 land 组成，地理上指伸向海中的海角或位于山脉前方的一片陆地。',[1,'海岸地貌','The lighthouse stands on a rocky foreland projecting into the sea, where ships can see its warning light before approaching the bay.','灯塔建在伸入海中的岩石海角上，船只靠近海湾前就能看到警示灯。','The lighthouse stands on a rocky foreland projecting into the sea, / where ships can see its warning light / before approaching the bay.','可数名词；依地理语境可指向海中突出的陆地，也可指山地前方的地区。','岩岸向海中突出，符合 foreland 的海角义。'],['The map marked the deep ocean trench as a foreland because it lay far beneath the sea and projected no land outward.','The map marked the rocky cape projecting into the sea as a foreland.','海底深沟不是向海中伸出的陆地。'],[[1,'A coastal foreland is?',['land projecting out into the sea','a deep channel under the ocean','a bridge across a river'],0,'foreland 可指伸入海中的陆地。'],[1,'Which place may be called a foreland?',['a cape jutting into the water','a cave far inland','a hill entirely beneath the sea'],0,'向海中突出的海角符合 foreland。'],[1,'A foreland in front of a mountain range is?',['land lying ahead of the range','a peak behind the range','a cloud above the range'],0,'foreland 也可指山脉前方的一片陆地。'],[1,'Choose the natural phrase.',['a rocky foreland on the coast','a foreland under the deep seabed','foreland of a forecast'],0,'沿海岩石海角可称 foreland。']]);
P('foreleg','由 fore 与 leg 组成，指四足动物位于身体前部的一条腿。',[1,'动物护理','The veterinarian examined the horse’s foreleg after it began limping, checking the hoof and lower joint for swelling.','马开始跛行后，兽医检查了它的前腿，查看蹄部和下方关节是否肿胀。','The veterinarian examined the horse’s foreleg / after it began limping, / checking the hoof and lower joint for swelling.','可数名词；动物解剖用语，区别于 hind leg 后腿。','跛行后检查前部肢体即 foreleg。'],['The dog injured a rear leg, but the vet recorded it as a foreleg.','The dog injured a rear leg, and the vet recorded it as a hind leg.','身体前部的是 foreleg；hind leg 指后腿。'],[[1,'A quadruped’s foreleg is?',['one of its front legs','one of its rear legs','a tail bone'],0,'foreleg 指四足动物的前腿。'],[1,'Which animal part is a foreleg?',['the front leg of a horse','the rear leg of a dog','a bird’s wing feather'],0,'马身体前部的腿是 foreleg。'],[1,'A vet examines a foreleg when?',['the animal has injured a front limb','the animal has a broken tail only','the animal has lost a collar'],0,'前肢受伤时需检查 foreleg。'],[1,'Choose the opposite term.',['hind leg','forehead','forecaster'],0,'hind leg 指后腿，与 foreleg 相对。']]);
P('forelimb','由 fore 与 limb 组成，解剖学中指脊椎动物前部的附肢，可为腿、臂、鳍或翅。',[1,'比较解剖','A bat’s forelimb has elongated finger bones supporting the wing membrane, although it serves a different function from a human arm.','蝙蝠的前肢具有支撑翼膜的细长指骨，尽管其功能不同于人的手臂。','A bat’s forelimb has elongated finger bones / supporting the wing membrane, / although it serves a different function from a human arm.','可数名词，泛指脊椎动物前附肢；具体形态可为翼、鳍、臂或前腿。','蝙蝠的翼是由前肢改造而来，说明 forelimb 不限于腿。'],['The zoologist labelled a horse’s rear leg a forelimb because it was located at the back of the animal.','The zoologist labelled a horse’s front leg a forelimb because it was located at the front of the animal.','foreleg 指前腿；后腿受伤应记录为 hind leg。'],[[1,'A vertebrate forelimb is?',['a front appendage such as an arm, wing, flipper, or front leg','a tail or rear-only appendage','an internal organ in the abdomen'],0,'forelimb 是脊椎动物身体前部的附肢。'],[1,'A bird’s wing is anatomically a modified?',['forelimb','hind limb','tail feather'],0,'鸟翼属于前肢的演化形式。'],[1,'Which is a forelimb?',['a dog’s front leg','a dog’s rear leg','a fish’s tail fin'],0,'狗的前腿属于 forelimb。'],[1,'Choose the contrasting term for a rear appendage.',['hind limb','forehead','forecaster'],0,'hind limb 指后肢，与 forelimb 相对。']]);
P('foreseeable','由 foresee 加 -able 构成；foresee 是 fore“预先”与 see“看见”组合，表示能够提前预料的。',[1,'项目管理','The schedule includes a reserve day for foreseeable delays, such as routine inspections or minor equipment repairs.','日程预留了一天应对可预见的延误，例如常规检查或小型设备维修。','The schedule includes a reserve day for foreseeable delays, / such as routine inspections / or minor equipment repairs.','形容词，常见 foreseeable future/problem/risk；指能够提前预料，不代表一定会发生。','检查和小修造成的延误可提前预料，适合安排缓冲时间。'],['The bridge closure was foreseeable because engineers had announced it months earlier, yet the manager claimed nobody could anticipate it.','The bridge closure was unforeseeable because no warning or prior sign had appeared.','已有数月提前公告说明事件可预见，不是不可预见。'],[[1,'A foreseeable risk is one that?',['can reasonably be anticipated','has already been repaired','cannot be imagined under any circumstances'],0,'foreseeable 指能够预料的。'],[1,'The foreseeable future means?',['the near period that can reasonably be anticipated','a time no one can ever predict','a date in the distant past'],0,'foreseeable future 指可预见的未来阶段。'],[1,'Which delay is foreseeable?',['a scheduled annual inspection','a completely unknown event with no warning signs','a fictional event in a novel'],0,'定期检查是可以提前预见的安排。'],[1,'Does foreseeable mean certain to happen?',['No; it means possible to anticipate.','Yes; it guarantees the event.','No; it means already completed.'],0,'可预见不等于必然发生。']]);
P('foreshadow','由 fore-“预先”与 shadow“影子”组成，表示某迹象预示之后发生的事件，尤其用于故事或发展模式。',[1,'文学阅读','The early scene in which the lighthouse fails to shine foreshadows the shipwreck that occurs several chapters later.','小说开头灯塔熄灭的场景，预示了几章后发生的船难。','The early scene in which the lighthouse fails to shine / foreshadows the shipwreck / that occurs several chapters later.','及物动词，常以事件、危险或结局为宾语；线索先出现，事件随后发生。','灯塔熄灭的早期线索预示之后船难，符合 foreshadow。'],['The first chapter foreshadowed the storm by mentioning it only after the storm had ended and all consequences were known.','The first chapter described the storm after it had ended and all consequences were known.','foreshadow 要求线索先于事件；事后叙述不是预示。'],[[1,'A detail foreshadows a later event when it?',['gives an earlier hint of what will happen','explains something only after it is over','has no connection to later events'],0,'foreshadow 指先出现的迹象预示后事。'],[1,'A darkening sky in a story may foreshadow?',['an approaching storm','a party held the previous year','a character’s shoe size'],0,'乌云可作为风暴将至的预示。'],[1,'Which sentence uses foreshadow correctly?',['The opening warning foreshadows the later collapse.','The warning foreshadowed the event after it had happened.','The warning foreshadows nothing and has no relation to the plot.'],0,'开头的警告可预示后来的事故。'],[1,'Foreshadow is often used when discussing?',['narrative clues and later plot events','the exact width of a table','a list of today’s groceries'],0,'该词常用于文学叙事分析。']]);
P('foreshorten','由 fore 与 shorten 组成，在绘画中指按透视把朝向观察者的物体表现得较短；也可表示缩短长度或时间。',[1,'绘画教学','The artist foreshortened the outstretched arm so it appeared shorter on the canvas as it pointed toward the viewer.','画家用透视法缩短伸出的手臂，使它在指向观者时显得更短。','The artist foreshortened the outstretched arm / so it appeared shorter on the canvas / as it pointed toward the viewer.','可指透视画法使物体显短，也可泛指缩短时间或长度。艺术义不是把真实肢体截短。','手臂在画面上因朝向观者而显短，体现 foreshorten 的透视义。'],['The painter foreshortened the arm by making it appear longer and larger as it pointed toward the viewer.','The painter enlarged the arm in perspective so it appeared longer and larger as it pointed toward the viewer.','foreshorten 会使透视方向上的物体在画面中显得缩短，不是拉长。'],[[1,'In perspective drawing, to foreshorten an arm is to?',['depict it shorter because it points toward the viewer','remove it from the canvas entirely','paint it a different colour only'],0,'foreshorten s1 指利用透视缩短视觉长度。'],[1,'A manager foreshortened the meeting by?',['reducing its planned duration','adding three hours to it','moving it to a larger room'],0,'s2 泛指缩短时间长度。'],[1,'Why might a leg look foreshortened in a painting?',['it extends toward the viewer in perspective','it is hidden behind the canvas','the model is standing far away facing sideways'],0,'朝向观者的肢体会因透视显短。'],[1,'Which action foreshortens a route?',['choosing a shortcut that reduces its length','adding a long detour','measuring it without changing it'],0,'采用捷径可缩短路线。']]);
P('foresightedness','由 foresighted 加 -ness 构成，指规划时审慎考虑未来后果的先见与远虑。',[1,'公共预算','The council’s foresightedness showed in its decision to repair drainage before new housing increased runoff across the valley.','市议会提前维修排水系统，展现了远见，因为新住宅建成后会增加山谷径流。','The council’s foresightedness showed in its decision to repair drainage / before new housing increased runoff / across the valley.','不可数名词；侧重规划时预估长远影响并提前准备，近义 foresight。','在新住宅造成更多径流前先修排水系统，体现 foresightedness。'],['The council showed foresightedness by ignoring the published flood projections and leaving every drain blocked until houses were inundated.','The council showed poor planning by ignoring the published flood projections and leaving every drain blocked.','无视预测且不采取预防行动表现缺乏远见。'],[[1,'Foresightedness is the ability to?',['consider future consequences when planning','forget all past experience','make a decision without looking ahead'],0,'foresightedness 指考虑未来的远见。'],[1,'Which decision shows foresightedness?',['funding flood defences before new homes are built','waiting until the town is underwater to inspect drains','spending every reserve on a short-lived display'],0,'提前防洪体现长远规划。'],[1,'A foresighted planner asks?',['what effects might this choice have later?','how can we ignore every future risk?','what happened in an unrelated meeting?'],0,'评估未来影响是有远见的规划方式。'],[1,'Choose the closest synonym.',['foresight','forgetfulness','carelessness'],0,'foresight 指先见、远虑。']]);
P('forestall','由 fore-“预先”与 stall“拖延、阻挡”构成，表示在问题发生前采取行动阻止，也可表示抢在他人之前行动。',[1,'安全预防','The clinic added a second appointment desk to forestall long queues before the seasonal vaccination campaign began.','季节性疫苗接种活动开始前，诊所增设了第二个预约窗口，以防排长队。','The clinic added a second appointment desk / to forestall long queues / before the seasonal vaccination campaign began.','s1 指预先阻止问题；s2 指抢在他人之前取得优势或发言。','活动开始前增设窗口以阻止队伍形成，体现 s1。'],['The clinic forestalled queues by closing the only appointment desk and refusing every booking.','The clinic caused queues by closing the only appointment desk and refusing every booking.','关闭唯一窗口会造成排队，不是预先阻止排队。'],[[1,'To forestall a delay is to?',['act beforehand to prevent it','wait until it becomes unavoidable','record how long it lasted afterward'],0,'forestall s1 表示提前采取行动阻止。'],[2,'A bidder forestalled competitors by?',['submitting an offer before they could act','waiting until after the sale ended','withdrawing every offer'],0,'forestall s2 可指抢先一步占得优势。'],[1,'Which measure may forestall a fire?',['repairing faulty wiring before it overheats','ignoring sparks until flames spread','blocking the emergency exit'],0,'事先修理线路可防止火灾发生。'],[2,'“She forestalled the question” means she?',['answered or addressed it before others raised it','waited for someone else to ask it','forgot the question entirely'],0,'抢在提问前回应体现先行处理。']]);
P('forestation','由 forest 加 -ation 构成，指在开阔地上种植树木并建立森林的过程。',[1,'生态修复','The forestation project planted native trees on degraded farmland, creating shelter belts that will reduce erosion over time.','造林项目在退化农田上种植本土树木，建立防护林带以逐渐减少侵蚀。','The forestation project planted native trees on degraded farmland, / creating shelter belts / that will reduce erosion over time.','不可数名词；描述建立森林的植树过程，可与 reforestation（重新造林）区分。','在无林退化土地上种树建立林地属于 forestation。'],['The forestation project removed every tree and converted an existing forest into bare land.','The deforestation project removed every tree and converted the forest into bare land.','砍伐清除森林是 deforestation，与建立林地的 forestation 相反。'],[[1,'Forestation is?',['establishing forest by planting trees on open land','cutting down every tree in a woodland','measuring the age of a single leaf'],0,'forestation 指植树造林。'],[1,'Which activity is forestation?',['planting native trees across degraded open land','clearing a forest for construction','painting a picture of a forest'],0,'在开阔土地建立林地是造林。'],[1,'Forestation may help reduce?',['soil erosion through tree cover','the number of roots in every tree to zero','all rainfall in a region'],0,'树木根系和覆盖能帮助减少土壤侵蚀。'],[1,'Choose the closest related verb.',['afforest','deforest','defeat'],0,'afforest 表示植树造林。']]);
P('forester','由 forest 加施事后缀 -er 构成，指受过训练、负责种植、保护或管理森林的人。',[1,'林地管理','The forester marked nesting trees that logging crews must avoid and scheduled a survey to check the woodland’s health.','林务员标记了伐木队必须避开的筑巢树，并安排调查以检查林地状况。','The forester marked nesting trees / that logging crews must avoid / and scheduled a survey to check the woodland’s health.','可数名词；从事森林保护、培育或管理，不单指伐木工。','标记生态敏感树木并监测林地的人是 forester。'],['The forester was a cashier who sold cinema tickets and had no responsibility for trees or woodland.','The forester was a woodland manager responsible for protecting and monitoring the trees.','售票员与森林管理职责无关。'],[[1,'A forester’s work may include?',['protecting and managing woodland','repairing aircraft engines only','selling tickets at a cinema'],0,'forester 指森林管理和保护人员。'],[1,'Who should identify trees to preserve during a logging plan?',['a trained forester','a film editor','a river pilot'],0,'林务员熟悉树木与森林管理。'],[1,'A forester differs from a logger because the forester may focus on?',['long-term woodland care and conservation','cutting trees without any plan','forecasting tomorrow’s rain'],0,'森林管理者会关注林地长期健康。'],[1,'Choose the natural phrase.',['consult a forester about woodland health','consult a forester about a passport stamp','a forester of the weather report'],0,'林地健康问题可咨询 forester。']]);
P('forestry','由 forest 加 -ry 构成，指对森林的管理与研究，可兼顾木材生产和生态保护。',[1,'资源管理','The forestry plan limits annual timber harvests and protects stream buffers so the woodland can regenerate while supporting local jobs.','林业计划限制年度木材采伐并保护溪流缓冲带，使林地在支持本地就业的同时能够再生。','The forestry plan limits annual timber harvests / and protects stream buffers / so the woodland can regenerate while supporting local jobs.','不可数领域名词；包括森林培育、采伐管理、保护和资源规划。','计划协调木材生产与林地再生，属于 forestry 管理。'],['The forestry programme cut every tree without replanting or considering soil, wildlife, or future woodland growth.','The programme was unsustainable logging because it removed trees without replanting or conservation.','不考虑恢复和生态的滥伐不是可持续的 forestry 管理。'],[[1,'Forestry concerns?',['the management and study of forests','the design of city traffic lights','the training of ocean pilots'],0,'forestry 指林业及森林管理。'],[1,'A forestry plan might set rules for?',['timber harvests and forest conservation','restaurant opening hours','the number of films made'],0,'森林计划会管理木材采伐与保护。'],[1,'Sustainable forestry aims to?',['use forest resources while allowing woodland to recover','remove all trees permanently','prevent any plant from growing'],0,'可持续林业需要兼顾利用与森林恢复。'],[1,'Choose the natural phrase.',['a degree in forestry','forestry to ring the bell','forestry of a shoe'],0,'a degree in forestry 是自然搭配。']]);
P('forked','由 fork 加 -ed 构成形容词，表示从一条主干或路线分成两个部分。',[1,'植物形态','The botanist photographed a forked stem where one shoot divided into two branches just above the soil.','植物学家拍下了分叉的茎：一条嫩枝刚出土便分成两个枝条。','The botanist photographed a forked stem / where one shoot divided into two branches / just above the soil.','形容词；可描述枝条、道路、闪电或工具末端分叉。','一条主茎分成两枝，体现 forked。'],['The forked path had one unbroken route with no branch or split anywhere along it.','The straight path had one unbroken route with no branch or split anywhere along it.','没有分支的道路不是 forked。'],[[1,'A forked branch?',['splits into two or more parts','ends in a smooth unbroken circle','is made only of water'],0,'forked 表示分叉的。'],[1,'Which road is forked?',['one route divides into two directions','one road remains straight and unbranched','a path ends at a wall'],0,'道路分成两个方向即出现分叉。'],[1,'A forked lightning bolt appears?',['split into branching streaks','as a single perfectly straight line only','inside a closed book'],0,'闪电分叉呈现支状路径。'],[1,'Choose the natural phrase.',['a forked tongue','a forked without a branch','forked to walk quickly'],0,'forked 可描述分叉的舌头或枝条。']]);
P('forlorn','源自古英语 forloren“失落的、被遗弃的”，与 lose 的历史形式相关；可指孤独悲伤、希望渺茫或地方荒凉。',[3,'废弃社区','At dusk, the forlorn railway station stood empty with broken windows and weeds covering the platform where trains had once arrived.','黄昏时，荒凉的火车站空无一人，窗户破碎，野草覆盖了曾经列车停靠的站台。','At dusk, the forlorn railway station stood empty / with broken windows and weeds covering the platform / where trains had once arrived.','s1 指孤苦悲伤；s2 指成功机会很小；s3 描写荒凉、破败的地方。','空站、破窗和野草构成荒凉景象，体现 s3。'],['The forlorn village was lively and well maintained, with crowded shops, fresh paint, and children playing in the square.','The thriving village was lively and well maintained, with crowded shops, fresh paint, and children playing in the square.','热闹且维护良好的村庄不显荒凉。'],[[1,'A forlorn person feels?',['lonely and sad after being left alone','triumphant after winning','certain of immediate success'],0,'forlorn s1 指孤独悲伤。'],[2,'A forlorn hope has?',['little chance of succeeding','a guaranteed victory','no connection to any goal'],0,'s2 指成功机会渺茫。'],[3,'A forlorn landscape looks?',['empty, bleak, and neglected','bright, crowded, and flourishing','newly built and well maintained'],0,'s3 描写空寂破败之地。'],[1,'Which character sounds forlorn?',['someone abandoned and grieving alone','someone celebrating with a cheering team','someone calmly preparing for a routine task'],0,'被独自留下且悲伤的人体现 s1。']]);
P('formalize','由 formal 加动词后缀 -ize 构成，表示给做法、关系或协议确立正式或固定形式。',[1,'组织治理','The two laboratories formalized their collaboration in a written agreement that set out data-sharing rules and review responsibilities.','两家实验室通过书面协议正式确立合作，明确了数据共享规则和审查职责。','The two laboratories formalized their collaboration in a written agreement / that set out data-sharing rules / and review responsibilities.','及物动词；常接 agreement、relationship、procedure；指正式定型，不只是讨论计划。','书面协议使双方合作形成正式安排，体现 formalize。'],['The laboratories formalized their agreement by leaving every term unwritten and refusing to decide who was responsible.','The laboratories discussed a possible agreement but did not formalize it because no terms were written down.','没有写明条款、也未确定责任，说明尚未正式确立协议。'],[[1,'To formalize an agreement is to?',['give it an official or fixed form','leave every term undecided','cancel all communication'],0,'formalize 指使安排或协议正式确定。'],[1,'Which action formalizes a partnership?',['signing a document that defines duties','mentioning a vague idea in conversation','avoiding every decision'],0,'签署明确职责的文件可使合作正式化。'],[1,'Formalize a procedure means?',['establish it in a fixed or official form','make it less clear','remove it from use'],0,'formalize 使程序成为正式、固定的做法。'],[1,'Choose the natural construction.',['formalize the agreement','formalize at the agreement','formalize to an agreement'],0,'formalize 是及物动词，直接接 agreement。']]);
P('formally','由 formal 加副词后缀 -ly 构成，表示正式地、依照规定或通过正式仪式与文件。',[1,'机构公告','The university formally opened the new library at a ceremony attended by students, staff, and the local community.','大学在学生、教职工和当地居民出席的仪式上正式开放了新图书馆。','The university formally opened the new library / at a ceremony attended by students, staff, / and the local community.','副词；可表示依正式程序，也可表示以庄重仪式进行；不等同于单纯穿着正式。','典礼标志图书馆正式开放，体现 formally。'],['The university formally opened the library by never announcing it, holding no ceremony, and keeping the doors locked.','The university quietly postponed the library opening and held no ceremony.','没有公告、典礼或开放行为，不能称 formally opened。'],[[1,'A building formally opens when it?',['is officially inaugurated or made available','is privately imagined','is demolished without notice'],0,'formally 表示正式地举行开放或启动。'],[1,'Which action is formally recorded?',['a signed decision entered into the official minutes','an unspoken thought','a rumour with no document'],0,'正式会议记录使决定得到官方记载。'],[1,'Formally can refer to?',['an official procedure or set ceremony','the colour of a wall only','a private guess'],0,'formally 可表示按正式方式或仪式进行。'],[1,'Choose the natural phrase.',['formally apologise to the client','formally to the client apologises','formal the client apologised'],0,'formally 可修饰动词 apologise。']]);
P('formation','源自拉丁语 formatio“形成、塑造”，经法语进入英语；可指事物形成过程，也指人或物的排列队形。',[1,'地质学','The formation of the limestone began as shells accumulated on the seabed and hardened under layers of sediment.','石灰岩的形成始于海床上的贝壳堆积，并在沉积层下逐渐硬化。','The formation of the limestone began / as shells accumulated on the seabed / and hardened under layers of sediment.','s1 指形成的过程；s2 指排列好的群体或构造，如 flight formation 或 rock formation。','贝壳堆积并硬化构成石灰岩的形成过程，体现 s1。'],['The rock formation happened only after the limestone was already fully formed and no process or change occurred.','The rock formation was a visible arrangement of limestone layers along the cliff.','s2 可指岩石构造或排列，不是“形成后没有构造”的空过程。'],[[1,'The formation of a cloud describes?',['the process by which it comes into being','the flight pattern of an aircraft','a note at the bottom of a page'],0,'formation s1 表示形成过程。'],[2,'Aircraft flying in formation are?',['arranged in a coordinated pattern','each parked in separate hangars','moving randomly with no relation'],0,'formation s2 指群体排列的队形。'],[1,'Which sentence uses formation as a process?',['The formation of the valley took millions of years.','The jets held a V-shaped formation.','The players kept their formation on the field.'],0,'山谷形成的过程对应 s1。'],[2,'A rock formation is?',['a recognisable arrangement or structure of rock','the time a rock was purchased','a person who studies weather'],0,'formation s2 可指地质构造。']]);
P('formative','由 form 加形容词后缀 -ative 构成，表示与成长形成有关，或对之后性格、发展影响很大的。',[1,'教育经历','Her formative years at the village school shaped her confidence, since teachers encouraged every student to lead a project and speak publicly.','她在乡村学校度过的成长时期塑造了自信，因为老师鼓励每个学生负责项目并公开发言。','Her formative years at the village school shaped her confidence, / since teachers encouraged every student / to lead a project and speak publicly.','形容词；常见 formative years/experience/influence，强调塑造后续发展的影响。','早年的经历对后来性格产生塑造作用，符合 formative。'],['The formative experience had no effect on his later character, choices, or development whatsoever.','The inconsequential experience had no effect on his later character or development.','完全没有后续影响的经历不能称为 formative。'],[[1,'A formative experience is one that?',['strongly shapes later growth or character','happens after every outcome is settled','has no effect on a person'],0,'formative 指对之后形成有塑造作用的。'],[1,'A child’s formative years are?',['years when important development and shaping occur','the years after the child has retired','a period with no learning or growth'],0,'formative years 是成长形成的重要时期。'],[1,'Which influence is formative?',['a mentor’s guidance changes how a student approaches research','a brief unrelated delay changes nothing','a label is printed on a folder'],0,'持续指导塑造学生的研究方式，属于 formative influence。'],[1,'Choose the natural phrase.',['a formative stage of development','formative at the umbrella','a formative yesterdayly'],0,'formative 可修饰 stage。']]);
P('formulaic','由 formula 加 -ic 构成，表示依靠固定套话或重复模式、缺乏新意的。',[1,'电影评论','The dialogue felt formulaic because every character repeated familiar catchphrases and the plot followed the same predictable turns as earlier films.','对白显得刻板，因为每个角色都重复熟悉的口号，情节也沿着以往电影中相同的套路发展。','The dialogue felt formulaic / because every character repeated familiar catchphrases / and the plot followed the same predictable turns as earlier films.','形容词，常修饰 language、response、plot；批评内容套用固定公式而缺少新意。','重复套话并沿用可预测情节，体现 formulaic。'],['The formulaic reply was completely original, specific to the question, and unlike anything the speaker had said before.','The spontaneous reply was completely original, specific to the question, and unlike anything the speaker had said before.','独特且针对问题的即兴回答并非套话式 formulaic。'],[[1,'A formulaic response is?',['built from familiar fixed phrases with little freshness','carefully original and specific','a silent gesture with no pattern'],0,'formulaic 指套用固定模式、缺少新意。'],[1,'Why might a critic call a film plot formulaic?',['it repeats a predictable sequence used in many films','it develops an unprecedented structure','it has no story at all'],0,'重复常见套路会显得刻板。'],[1,'Which sentence sounds formulaic?',['“Thank you for your valuable feedback; we will get back to you soon” repeated in every case','a direct answer tailored to the detailed question','an original explanation supported by new evidence'],0,'每次机械重复的固定回复带有套话感。'],[1,'Formulaic most nearly means?',['following a set pattern with little originality','mathematically proven in every case','made of liquid'],0,'formulaic 描述固定套式、缺乏新颖。']]);
P('formulation','由 formulate 加 -ion 构成，可指把想法、理论或政策组织成清楚表述，也可指按特定配方制成的混合物。',[1,'政策研究','The policy’s formulation took several meetings because the team had to express the goals clearly without promising services the budget could not support.','这项政策的表述经过了多次会议，因为团队必须清楚说明目标，同时不能承诺预算无法支持的服务。','The policy’s formulation took several meetings / because the team had to express the goals clearly / without promising services the budget could not support.','s1 指观点或政策的表述方式；s2 指依特定配方制备的制剂或混合物。','团队斟酌如何准确表达政策目标，体现 formulation s1。'],['The pharmacist checked the formulation of the cream by reading its wording in a policy debate rather than checking its ingredients.','The pharmacist checked the formulation of the cream by reviewing its ingredients and proportions.','药品 formulation s2 指配方或制剂，应检查成分比例而非政策文字。'],[[1,'A policy’s formulation is?',['the way its ideas and terms are expressed','a dose of medicine in a bottle','the arrangement of aircraft'],0,'formulation s1 指思想或政策的表述方式。'],[2,'A pharmaceutical formulation is?',['a preparation made to a specified recipe','a debate speech about public policy','a footnote in a report'],0,'formulation s2 指特定配方制剂。'],[1,'Why revise the formulation of a rule?',['to make its meaning clearer and more precise','to change the paper’s colour only','to hide the rule from readers'],0,'修改措辞可使规则表述清晰。'],[2,'A chemist evaluates a product formulation by?',['checking its ingredients and proportions','counting its pages','asking how many people attended a meeting'],0,'制剂配方由成分及其比例构成。']]);
P('forte','源自法语 fort“强的”，进入英语后可指个人擅长之事，也可在音乐记号中表示强奏。',[1,'个人能力','Negotiation is her forte, so the director asked her to lead talks with the supplier after repeated delivery delays.','谈判是她的强项，因此供应商多次延迟交货后，主管请她带队协商。','Negotiation is her forte, / so the director asked her to lead talks / with the supplier after repeated delivery delays.','s1 指特长；s2 为音乐术语 forte，标记强奏，通常写作 f。','主管让她负责谈判，因为这正是她擅长的领域。'],['The pianist played the marked forte passage as softly as possible, barely audible across the room.','The pianist played the marked piano passage softly, barely audible across the room.','音乐记号 forte 表示强奏，与轻奏 piano 相反。'],[[1,'Someone’s forte is?',['a skill they do especially well','a task they have never attempted','a musical instrument’s price'],0,'forte s1 指某人的强项。'],[2,'In a score, forte tells a musician to play?',['loudly','silently','with no rhythm'],0,'音乐术语 forte 表示强奏。'],[1,'Which might be described as a chef’s forte?',['creating balanced sauces','repairing satellites','forecasting tides'],0,'擅长的烹饪技能可称为 forte。'],[2,'The symbol f above a musical passage commonly means?',['forte, or loud','piano, or soft','pause forever'],0,'f 是 forte 的常见力度记号。']]);
P('forthright','由 forth 与 right 组合，表示直率坦白地表达；较罕见的旧名词义指一条直路或直线行程。',[1,'工作反馈','The editor was forthright about the draft’s weak evidence, but she also suggested specific sources that could strengthen the argument.','编辑坦率指出草稿证据薄弱，同时提出了可以加强论证的具体来源。','The editor was forthright about the draft’s weak evidence, / but she also suggested specific sources / that could strengthen the argument.','s1 形容词“直率的”；s2 副词“直率地”；s3 罕见旧名词“直路”。','编辑直接指出问题并给出建设性建议，体现坦白直率。'],['The forthright editor hid every criticism, refused to state an opinion, and left the writer guessing about the draft.','The evasive editor hid every criticism and left the writer guessing about the draft.','隐瞒意见并让作者猜测是回避，不是 forthright。'],[[1,'A forthright answer is?',['honest and direct','deliberately vague','unrelated to the question'],0,'forthright s1 指坦率直接。'],[2,'She spoke forthright about the error means she spoke?',['openly and directly','in a whisper with no opinion','only in a foreign language'],0,'s2 作副词表示直率地。'],[3,'In a rare old use, a forthright is?',['a straight course or path','a fenced orchard','a musical note played loudly'],0,'forthright s3 是罕见的旧名词义“直路”。'],[1,'Which colleague is forthright?',['one who states concerns honestly and clearly','one who hides every concern','one who invents a different report'],0,'坦白表达担忧体现 forthright。']]);
P('fortification','由 fortify 加 -ication 构成；fortify 与拉丁语 fortis“坚固的”相关，可指防御工事，也可指强化或营养添加过程。',[2,'食品营养','The fortification of flour with iron helped address dietary deficiencies, and the package listed the added nutrient on its label.','面粉强化添加铁元素，有助于改善膳食缺乏；包装标签注明了添加的营养素。','The fortification of flour with iron helped address dietary deficiencies, / and the package listed / the added nutrient on its label.','s1 指防御建筑或墙垣；s2 指使某物更强，亦可指给食品添加营养。','向面粉加入铁元素提高其营养含量，体现 fortification s2。'],['The fortification around the city was a nutrient added to flour, not a wall or defensive structure.','The fortification around the city was a defensive wall, while iron was added to the flour.','城市周围的 fortification 指防御工事；铁强化食品是另一义。'],[[1,'A fortification around a castle is?',['a wall or structure built for defence','a recipe for bread','a weather forecast'],0,'fortification s1 指防御工事。'],[2,'Nutritional fortification of cereal may involve?',['adding a vitamin or mineral','removing every nutrient','building a stone wall around a field'],0,'营养强化通过添加维生素或矿物质进行。'],[1,'Why construct fortifications around a port?',['to defend it from attack','to help food absorb iron','to mark a flowerbed'],0,'防御工事用于保护地点免受攻击。'],[2,'Which process is food fortification?',['adding iodine to salt','painting a warehouse wall','removing a serving from a plate'],0,'向食盐中添加碘属于食品强化。']]);

})();
